  {"id":"br17","name":"南瓜小米粥 + 煎蛋 + 拍黄瓜","type":"breakfast","spicy":false,"tags":["养胃","适合老人","粗粮"],"time":25,"difficulty":"简单","ingredients":[{"name":"小米","amount":40,"unit":"g","category":"米面粮油"},{"name":"南瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["南瓜去皮切小块，和淘洗好的小米一起加约 6 倍清水，大火烧开转小火煮 20 分钟。","趁煮粥的空档：黄瓜拍裂切段，加蒜末、1 克盐、香醋 1 勺和几滴香油拌匀。","平底锅少油，小火煎两个鸡蛋至喜欢的熟度。","粥熬到南瓜软烂、能轻松压成泥即可，三样一起上桌。"],"nutrition":{"kcal":410,"protein":16,"fat":16,"carbs":48,"calcium":90,"iron":3},"tip":"南瓜自带甜味不用加糖，小米养胃，早上肠胃负担小。"},
  {"id":"br18","name":"黄金蛋炒饭 + 纯牛奶","type":"breakfast","spicy":false,"tags":["快手","成本超低","儿童友好"],"time":10,"difficulty":"简单","ingredients":[{"name":"大米","amount":70,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"纯牛奶","amount":150,"unit":"ml","category":"奶品豆制品"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["隔夜米饭提前打散，鸡蛋打成蛋液倒入饭中拌匀，让每粒米都裹上蛋液。","热锅下 1 瓷勺油，倒入米饭中火快炒 2-3 分钟至粒粒分明。","加胡萝卜丁翻炒 1 分钟，用 1 克盐和少许生抽沿锅边淋入调味。","撒葱花翻匀出锅，配一杯热牛奶。"],"nutrition":{"kcal":470,"protein":17,"fat":17,"carbs":62,"calcium":210,"iron":2},"tip":"用隔夜饭消耗剩饭零浪费，蛋液裹饭再炒，少油也能粒粒金黄。"},
  {"id":"br19","name":"奶香玉米糊 + 水煮蛋 + 蒸紫薯","type":"breakfast","spicy":false,"tags":["粗粮","适合老人","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"玉米糊","amount":40,"unit":"g","category":"米面粮油"},{"name":"纯牛奶","amount":150,"unit":"ml","category":"奶品豆制品"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"紫薯","amount":120,"unit":"g","category":"蔬菜水果"}],"steps":["紫薯洗净切段，和鸡蛋一起上蒸锅，水开后蒸 12 分钟。","玉米糊先用少量凉水调开成无颗粒的浆，下锅才不结块。","锅中一碗水烧开转中小火，倒入玉米浆边煮边搅 2 分钟至浓稠冒泡。","关火后兑入牛奶搅匀成奶香糊，配水煮蛋和紫薯上桌。"],"nutrition":{"kcal":440,"protein":15,"fat":10,"carbs":72,"calcium":220,"iron":2.2},"tip":"粗粮加薯类，膳食纤维丰富促进肠道蠕动，适合久坐人群和老人。"},
  {"id":"br20","name":"虾仁滑蛋粥 + 蒸红薯","type":"breakfast","spicy":false,"tags":["高蛋白","养胃"],"time":30,"difficulty":"简单","ingredients":[{"name":"大米","amount":60,"unit":"g","category":"米面粮油"},{"name":"冷冻虾仁","amount":80,"unit":"g","category":"水产海鲜"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"红薯","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["大米加约 8 倍清水，大火烧开转小火熬 25 分钟成稠粥；红薯切块同步上锅蒸熟。","虾仁解冻后用少许料酒和姜丝抓匀，腌 5 分钟去腥。","粥滚时下虾仁，中火煮 2 分钟至完全变红卷曲。","转小火淋入蛋液，停几秒再轻搅出蛋花，加 2 克盐和几滴香油，撒葱花即成。"],"nutrition":{"kcal":460,"protein":24,"fat":8,"carbs":73,"calcium":80,"iron":2},"tip":"虾仁低脂高蛋白，最后下锅口感才弹嫩；红薯补足碳水更抗饿。"},
  {"id":"br21","name":"脆底煎饺 + 豆浆 + 凉拌黄瓜","type":"breakfast","spicy":false,"tags":["快手","中式"],"time":15,"difficulty":"简单","ingredients":[{"name":"速冻猪肉煎饺","amount":8,"unit":"个","category":"米面粮油"},{"name":"豆浆（或黄豆现打）","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["平底锅刷一层油，冻饺子不解冻直接码入，小火煎 1 分钟定底。","倒入没过饺子三分之一的清水，盖盖中火焖 8 分钟，让蒸汽把馅焖熟。","开盖等水收干，再小火煎 1 分钟至底部金黄酥脆。","黄瓜拍碎切块，加蒜末、1 克盐、香醋 1 勺和几滴香油拌匀，配热豆浆上桌。"],"nutrition":{"kcal":450,"protein":20,"fat":19,"carbs":48,"calcium":120,"iron":2.5},"tip":"水煎法比油炸省油一半，配黄瓜解腻补维C，荤素平衡。"},
  {"id":"br22","name":"番茄鸡蛋疙瘩汤","type":"breakfast","spicy":false,"tags":["养胃","中式","成本超低"],"time":20,"difficulty":"简单","ingredients":[{"name":"面粉","amount":70,"unit":"g","category":"米面粮油"},{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"上海青","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["面粉放大碗里，边滴清水边用筷子快速画圈，搅成黄豆大小的絮状面疙瘩。","番茄切小块，热锅少油中火炒 2 分钟出红汤汁，加足量热水烧开。","拨入面疙瘩，边下边搅散，中火煮 3 分钟至全部浮起。","淋入蛋液搅出蛋花，放上海青烫软，加 2 克盐和几滴香油，撒葱花出锅。"],"nutrition":{"kcal":460,"protein":20,"fat":15,"carbs":58,"calcium":110,"iron":3},"tip":"一锅端的主食蛋白蔬菜全齐，汤汤水水暖胃，冬天早晨首选。"},
  {"id":"br23","name":"山药肉末粥 + 白灼上海青","type":"breakfast","spicy":false,"tags":["养胃","适合老人"],"time":35,"difficulty":"简单","ingredients":[{"name":"大米","amount":60,"unit":"g","category":"米面粮油"},{"name":"山药","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"猪肉末","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"上海青","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["肉末加生抽 1 瓷勺、少许料酒和姜末抓匀，腌 10 分钟入味去腥。","大米加约 8 倍清水大火煮开，放山药丁转小火熬 20 分钟至粥变稠。","下肉末迅速搅散防结团，再煮 5 分钟至肉色全白，加 2 克盐调味。","上海青放沸水烫 1 分钟捞出，淋少许蚝油摆盘，配粥上桌。"],"nutrition":{"kcal":420,"protein":16,"fat":12,"carbs":60,"calcium":130,"iron":2.6},"tip":"山药黏蛋白护胃，肉末提前腌过更嫩滑，粥品早餐也能有优质蛋白。"},
  {"id":"br24","name":"香煎馒头片 + 煎蛋 + 牛奶","type":"breakfast","spicy":false,"tags":["快手","成本超低","儿童友好"],"time":10,"difficulty":"简单","ingredients":[{"name":"馒头","amount":80,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"纯牛奶","amount":150,"unit":"ml","category":"奶品豆制品"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["馒头切 1 厘米厚片，一个鸡蛋加 1 克盐打散。","馒头片两面裹满蛋液，稍等片刻让蛋液吸进去一点，煎出来更软香。","平底锅刷油，小火每面煎 2 分钟至两面金黄。","锅边再煎一个鸡蛋，配热牛奶一起上桌。"],"nutrition":{"kcal":450,"protein":22,"fat":19,"carbs":45,"calcium":230,"iron":2.4},"tip":"隔夜馒头裹蛋液煎，外脆里软还不浪费，比油条健康得多。"},
  {"id":"br25","name":"肉松黄瓜饭团 + 豆浆","type":"breakfast","spicy":false,"tags":["带出门","儿童友好","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"大米","amount":80,"unit":"g","category":"米面粮油"},{"name":"肉松","amount":15,"unit":"g","category":"肉禽蛋"},{"name":"黄瓜","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"豆浆（或黄豆现打）","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["热米饭加几滴香油和少许盐拌匀，放至不烫手。","保鲜膜上铺米饭压平，中间放肉松和黄瓜条。","借助保鲜膜卷紧收口，来回压几下捏成结实的饭团。","装袋配豆浆，出门路上也能吃；黄瓜现切现包才够脆。"],"nutrition":{"kcal":450,"protein":20,"fat":10,"carbs":68,"calcium":90,"iron":2.2},"tip":"赶时间家庭的救星，前晚预约煮饭，早上5分钟就能带走。"},
  {"id":"br26","name":"花生酱香蕉吐司 + 牛奶","type":"breakfast","spicy":false,"tags":["快手","西式","带出门"],"time":5,"difficulty":"简单","ingredients":[{"name":"全麦吐司","amount":2,"unit":"片","category":"米面粮油"},{"name":"花生酱","amount":15,"unit":"g","category":"调味干货"},{"name":"香蕉","amount":1,"unit":"根","category":"蔬菜水果"},{"name":"纯牛奶","amount":200,"unit":"ml","category":"奶品豆制品"}],"steps":["吐司干锅小火烘 1 分钟至微脆。","两片吐司各抹一层薄薄的花生酱。","香蕉切片铺在其中一片上，合起对切成三角。","配一杯温牛奶，5 分钟搞定出门。"],"nutrition":{"kcal":470,"protein":17,"fat":15,"carbs":66,"calcium":260,"iron":2},"tip":"选配料表只有花生的纯花生酱，抹薄薄一层香而不腻热量可控。"},
  {"id":"br27","name":"酒酿窝蛋小圆子 + 蒸山药","type":"breakfast","spicy":false,"tags":["中式","小红书爆款"],"time":15,"difficulty":"简单","ingredients":[{"name":"糯米小圆子","amount":100,"unit":"g","category":"米面粮油"},{"name":"酒酿","amount":120,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"山药","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"冰糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["山药去皮切段上蒸锅，水开后蒸 12 分钟至筷子能扎透。","锅中水烧开下小圆子，中火煮至全部浮起。","加入酒酿和少许冰糖，再煮 1 分钟就好——酒酿久煮会发酸。","转小火在汤中间窝入一个鸡蛋，不要搅动，煮 3 分钟至蛋白凝固即可。"],"nutrition":{"kcal":430,"protein":11,"fat":8,"carbs":75,"calcium":60,"iron":1.8},"tip":"江南人的暖胃早餐，酒酿别久煮以免发酸；冰糖少放甜味更清爽。"},
  {"id":"br28","name":"葱油拌面 + 溏心蛋 + 烫生菜","type":"breakfast","spicy":false,"tags":["快手","中式","成本超低"],"time":15,"difficulty":"简单","ingredients":[{"name":"挂面","amount":80,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"生菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":20,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡蛋冷水下锅，水开后煮 6 分钟捞出过凉剥壳，就是刚好流心的溏心蛋。","小葱切长段，冷油下锅小火慢炸 5-6 分钟至焦黄出香，捞出葱段。","葱油中加生抽 2 勺、老抽半勺、白糖半勺，小火煮开成酱汁关火。","挂面煮约 3 分钟至熟，起锅前顺手烫熟生菜，捞出沥水，浇酱汁拌匀。","摆上对半切的溏心蛋，趁热拌开。"],"nutrition":{"kcal":440,"protein":17,"fat":13,"carbs":62,"calcium":70,"iron":2.6},"tip":"葱油可以周末一次熬一小罐冷藏，工作日早晨拌面3分钟搞定。"},
  {"id":"br29","name":"家庭版杂粮煎饼 + 豆浆","type":"breakfast","spicy":false,"tags":["中式","粗粮"],"time":20,"difficulty":"中等","ingredients":[{"name":"面粉","amount":50,"unit":"g","category":"米面粮油"},{"name":"玉米糊","amount":20,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"生菜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"甜面酱","amount":15,"unit":"g","category":"调味干货"},{"name":"豆浆（或黄豆现打）","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["面粉和玉米糊加水搅成能流动的稀面糊，静置 5 分钟。","平底锅刷薄油小火烧热，倒入面糊快速转锅摊成大薄饼。","磕入鸡蛋用铲背抹匀，撒葱花，小火烙 1-2 分钟至蛋液定型后翻面。","抹一层甜面酱，铺上生菜，卷起切段，配热豆浆。"],"nutrition":{"kcal":450,"protein":18,"fat":13,"carbs":62,"calcium":100,"iron":2.8},"tip":"在家复刻煎饼果子，不放薄脆油脂减半，杂粮糊升糖更平稳。"},
  {"id":"br30","name":"豆沙包 + 牛奶 + 水煮蛋","type":"breakfast","spicy":false,"tags":["快手","儿童友好"],"time":12,"difficulty":"简单","ingredients":[{"name":"速冻豆沙包","amount":2,"unit":"个","category":"米面粮油"},{"name":"纯牛奶","amount":200,"unit":"ml","category":"奶品豆制品"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"}],"steps":["蒸锅加水，豆沙包不用解冻直接摆上蒸屉。","洗净的鸡蛋放进下层水里一起煮，一锅两用。","大火烧开后转中火蒸 10 分钟，包子和蛋同时出锅。","牛奶加热至温热不烫口，一起上桌。"],"nutrition":{"kcal":420,"protein":16,"fat":11,"carbs":62,"calcium":240,"iron":2},"tip":"包子和蛋一锅同蒸省时省火，甜口早餐记得当天别再吃其他甜食。"},
  {"id":"m24","name":"红烧肉","type":"meat","spicy":false,"tags":["硬菜","经典","下饭"],"time":60,"difficulty":"中等","ingredients":[{"name":"五花肉","amount":90,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"冰糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"老抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"八角","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["五花肉切麻将块，冷水下锅加姜片和少许料酒，中火煮开撇净浮沫，捞出沥干。","锅中少油放冰糖约 10 粒，小火慢慢炒化至枣红色冒小泡，立刻下肉块翻炒裹上糖色。","加姜片、八角 1 颗、生抽 2 勺、老抽半勺，倒入热水没过肉块——用热水肉不发紧。","大火烧开转小火加盖焖 40 分钟，至筷子能轻松扎透。","开盖转大火收汁，勤翻动防糊底，汤汁浓稠发亮时尝味，不够咸补少许盐，撒葱花出锅。"],"nutrition":{"kcal":330,"protein":12,"fat":28,"carbs":7,"calcium":10,"iron":1.5},"tip":"五花肉脂肪较高，一餐一小碗即可，搭配绿叶菜更均衡。","heavy":true},
  {"id":"m25","name":"回锅肉","type":"meat","spicy":true,"tags":["川味","下饭神器","经典"],"time":30,"difficulty":"中等","ingredients":[{"name":"五花肉","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"青椒（菜椒不辣）","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"豆豉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["五花肉整块冷水下锅，加姜片和少许料酒，中火煮 20 分钟至筷子能扎透，捞出晾凉切薄片。","热锅少油，下肉片中小火煸 2-3 分钟，煸至肉片微卷出油、呈「灯盏窝」状。","把肉片拨到锅边，下豆瓣酱 1 勺和豆豉、蒜片，小火炒出红油和香味。","转大火下青椒块翻炒 1 分钟至断生，加生抽 1 勺和少许白糖提味即可出锅。"],"nutrition":{"kcal":320,"protein":12,"fat":27,"carbs":8,"calcium":20,"iron":1.6},"tip":"先煮后煸可逼出部分油脂，煸炒时不必再多放油。","heavy":true},
  {"id":"m26","name":"糖醋排骨","type":"meat","spicy":false,"tags":["经典","儿童最爱","硬菜"],"time":45,"difficulty":"中等","ingredients":[{"name":"猪肋排","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"冰糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["排骨剁小段冷水下锅，加姜片和少许料酒，中火煮开撇净浮沫，捞出洗净沥干。","热锅少油，下排骨中火煎 3-4 分钟至两面微黄，煎出香味。","下冰糖约 10 粒小火炒至融化裹匀，烹入香醋 2 勺、生抽 1 勺，加热水没过排骨。","大火烧开转中小火加盖焖 30 分钟至排骨软烂。","开盖大火收汁，汤汁浓稠冒大泡时再淋半勺香醋提酸香，翻匀裹亮，撒葱花出锅。"],"nutrition":{"kcal":310,"protein":18,"fat":20,"carbs":14,"calcium":60,"iron":1.8},"tip":"糖醋口味含糖较多，儿童喜欢但别天天做，一周一次刚好。","heavy":true},
  {"id":"m27","name":"玉米胡萝卜排骨汤","type":"soup","spicy":false,"tags":["适合老人","一锅出","家常"],"time":70,"difficulty":"简单","ingredients":[{"name":"猪肋排","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"甜玉米","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["排骨斩小块冷水下锅，加料酒 1 瓷勺和几片姜，大火煮开后撇净浮沫，捞出用温水冲洗干净，焯水能有效去腥。","甜玉米切小段，胡萝卜去皮切滚刀块备用。","排骨、玉米、胡萝卜和剩余姜片一起入汤锅，加足量热水没过食材两指，用热水炖汤更容易出鲜。","大火烧开后转小火，盖盖慢炖 50 分钟，炖到排骨用筷子能轻松扎透。","出锅前加盐约 2 克调味，再煮 1 分钟即可，起锅才放盐既控钠又不减鲜。"],"nutrition":{"kcal":280,"protein":17,"fat":16,"carbs":17,"calcium":55,"iron":1.5},"tip":"汤鲜来自食材本身，起锅再放盐，控钠又不减鲜味。"},
  {"id":"m28","name":"白萝卜筒骨汤","type":"soup","spicy":false,"tags":["适合老人","家常","成本超低"],"time":90,"difficulty":"简单","ingredients":[{"name":"猪筒骨","amount":200,"unit":"g","category":"肉禽蛋"},{"name":"白萝卜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["筒骨冷水下锅，加料酒 1 瓷勺，大火煮开撇去浮沫，捞出用温水冲洗干净。","筒骨和姜片放入汤锅，加足量热水没过，大火烧开后转小火盖盖炖 1 小时，汤色会慢慢发白。","中途水少了只添热水，千万别加冷水，否则汤就出不了奶白色。","白萝卜去皮切大块下锅，再炖 20 分钟，煮到萝卜半透明、筷子一扎就透。","加盐约 2 克调味，撒上葱花即可出锅。"],"nutrition":{"kcal":220,"protein":14,"fat":15,"carbs":7,"calcium":45,"iron":1.2},"tip":"骨头汤钙含量有限，吃汤里的肉和萝卜比只喝汤更有营养。"},
  {"id":"m29","name":"木须肉","type":"meat","spicy":false,"tags":["经典","家常","下饭"],"time":20,"difficulty":"简单","ingredients":[{"name":"猪里脊肉","amount":60,"unit":"g","category":"肉禽蛋"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"干木耳","amount":5,"unit":"g","category":"调味干货"},{"name":"黄瓜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["干木耳提前用温水泡发 20 分钟，撕成小朵；黄瓜切菱形片，里脊切薄片。","肉片加料酒半瓷勺、生抽半瓷勺、淀粉 1 小勺抓匀腌 10 分钟，淀粉能锁住水分让肉更嫩。","鸡蛋加 1 克盐打散，热锅热油倒入蛋液，凝固后铲成大块盛出。","锅中补少许油，下蒜片爆香，倒入肉片中大火滑炒至完全变色。","下木耳和黄瓜片，大火翻炒 1 分钟，木耳受热有噼啪声属正常。","回入鸡蛋，加生抽半瓷勺、盐 1 克，快速翻匀出锅。"],"nutrition":{"kcal":260,"protein":21,"fat":16,"carbs":8,"calcium":50,"iron":3},"tip":"木耳富含膳食纤维和铁，配鸡蛋瘦肉，营养搭配很全面。"},
  {"id":"m30","name":"肉末茄子","type":"meat","spicy":false,"tags":["下饭神器","家常","成本超低"],"time":25,"difficulty":"简单","ingredients":[{"name":"猪肉末","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"茄子","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["茄子切长条，撒 2 克盐拌匀腌 10 分钟，杀出水后用手挤干，这样下锅能少吸一半油。","锅中倒 1 瓷勺油烧热，下肉末中火炒散，炒到微微发黄出香。","加蒜末炒出香味，倒入茄条转中火翻炒约 3 分钟，炒到茄子完全软塌。","调入生抽 1 瓷勺、蚝油半瓷勺、白糖 1 小撮，翻炒均匀让茄条上色入味。","尝味不够再补少许盐，撒葱花出锅。"],"nutrition":{"kcal":250,"protein":12,"fat":17,"carbs":13,"calcium":25,"iron":1.4},"tip":"茄子先盐腌挤水，能少吸一半油，口感一样软糯入味。"},
  {"id":"m31","name":"蚂蚁上树","type":"meat","spicy":true,"tags":["川味","下饭神器","成本超低"],"time":20,"difficulty":"简单","ingredients":[{"name":"猪肉末","amount":40,"unit":"g","category":"肉禽蛋"},{"name":"龙口粉丝","amount":50,"unit":"g","category":"米面粮油"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["粉丝用温水泡 10 分钟至发软，用剪刀剪成几段，沥干备用。","热锅倒 1 瓷勺油，下肉末中火炒散，炒至微黄出香。","加姜末蒜末和豆瓣酱 1 小勺，转小火炒出红油，豆瓣酱本身够咸，后面不用再加盐。","倒入半碗热水和生抽半瓷勺烧开，下粉丝转中火边煮边翻拌。","煮约 2 分钟，汤汁收干、粉丝变得透亮时撒葱花出锅。"],"nutrition":{"kcal":320,"protein":10,"fat":13,"carbs":41,"calcium":20,"iron":1.5},"tip":"粉丝碳水较高，当主食吃就好，这餐米饭可以少盛半碗。"},
  {"id":"m32","name":"青椒炒猪肝","type":"meat","spicy":false,"tags":["补铁","快手","下饭"],"time":15,"difficulty":"简单","ingredients":[{"name":"猪肝","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"青椒（菜椒不辣）","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["猪肝切 3 毫米薄片，清水浸泡 10 分钟去血水，中途换一次水。","沥干后加料酒 1 瓷勺、淀粉 1 小勺抓匀，腌 5 分钟去腥锁嫩。","热锅热油，下猪肝大火快炒约 1 分钟，片片变色断生就立刻盛出，久炒会发硬发苦。","余油下姜丝蒜片爆香，倒入青椒块中大火炒至断生微软。","回入猪肝，沿锅边烹生抽 1 瓷勺和几滴香醋，大火翻匀马上出锅。"],"nutrition":{"kcal":210,"protein":21,"fat":10,"carbs":8,"calcium":15,"iron":22},"tip":"猪肝是补铁冠军，儿童孕妇每周吃1-2次即可，不宜过量。"},
  {"id":"m33","name":"电饭煲腊肠煲仔饭","type":"meat","spicy":false,"tags":["一锅出","粤式","小红书爆款"],"time":40,"difficulty":"简单","ingredients":[{"name":"腊肠","amount":25,"unit":"g","category":"肉禽蛋"},{"name":"大米","amount":50,"unit":"g","category":"米面粮油"},{"name":"上海青","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"老抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["大米淘洗两遍，按平时煮饭的水量放入电饭煲，水量可略少一点，饭粒更弹。","腊肠切薄片铺在米上，按下煮饭键。","趁煮饭烧一小锅水，水开后滴几滴油，下上海青烫 1 分钟捞出沥水。","小碗调酱汁：生抽 1 瓷勺、老抽几滴、白糖 1 小撮、香油几滴，搅到糖化开。","饭跳闸后摆上青菜、淋入酱汁，盖盖再焖 2 分钟，开盖拌匀就能吃。"],"nutrition":{"kcal":330,"protein":12,"fat":12,"carbs":44,"calcium":40,"iron":1.2},"tip":"腊肠钠含量高，铺少量提香即可，酱汁也要相应减盐。","solo":true},
  {"id":"m34","name":"香菇蒸肉饼","type":"meat","spicy":false,"tags":["适合老人","儿童友好","家常"],"time":25,"difficulty":"简单","ingredients":[{"name":"猪肉末","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"干香菇","amount":10,"unit":"g","category":"调味干货"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["干香菇温水泡发 30 分钟，挤干切碎，泡菇水留 2 瓷勺备用。","肉末加香菇碎、姜末、生抽 1 瓷勺、料酒半瓷勺、淀粉 1 小勺。","分两次倒入泡菇水，顺一个方向搅 2 分钟搅上劲，肉饼才嫩而不散。","肉馅摊入深盘压成约 1 厘米厚的圆饼，中间用勺背压个浅窝，受热更均匀。","蒸锅水开后放入，中大火蒸 12 分钟至完全熟透。","出锅撒葱花、淋几滴香油即可。"],"nutrition":{"kcal":250,"protein":15,"fat":19,"carbs":5,"calcium":20,"iron":1.8},"tip":"蒸制少油软嫩好消化，老人小孩都好嚼，比煎炸更健康。","heavy":true},
  {"id":"m35","name":"黑椒牛柳","type":"meat","spicy":false,"tags":["高蛋白","下饭","快手"],"time":20,"difficulty":"简单","ingredients":[{"name":"牛里脊","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"青椒（菜椒不辣）","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"杏鲍菇","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"黑胡椒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["牛里脊逆着纹路切成小指粗的条，加生抽 1 瓷勺、淀粉 1 小勺、几滴油抓匀腌 10 分钟。","杏鲍菇和青椒切成同样粗细的条，蒜切片。","热锅热油，下牛柳大火快炒约 1 分钟，表面变色立刻盛出，防止炒老。","余油下蒜片爆香，放杏鲍菇条中火炒 2 分钟炒软，再下青椒条炒到断生。","回入牛柳，加蚝油 1 瓷勺和现磨黑胡椒，大火翻炒 30 秒出锅。"],"nutrition":{"kcal":230,"protein":23,"fat":11,"carbs":9,"calcium":20,"iron":3},"tip":"牛里脊高蛋白低脂还补铁，健身增肌人群的优选部位。","heavy":true},
  {"id":"m36","name":"番茄肥牛","type":"meat","spicy":false,"tags":["小红书爆款","下饭神器","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"肥牛卷","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"番茄酱","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["烧一锅开水，肥牛卷下锅烫 10 秒，变色立即捞出沥水，去掉血沫和多余油脂。","番茄顶部划十字，开水烫一下撕去外皮，切成小块。","热锅倒 1 瓷勺油，下蒜末爆香，倒番茄块中火翻炒约 3 分钟，炒出浓稠的茄汁。","加番茄酱 1 瓷勺、半碗热水、生抽半瓷勺、白糖 1 小撮烧开。","下肥牛煮 1 分钟，加盐 1 克调味，撒葱花出锅，连汤带肉浇在米饭上最好吃。"],"nutrition":{"kcal":290,"protein":15,"fat":22,"carbs":9,"calcium":20,"iron":2.2},"tip":"肥牛先焯水去浮油，酸甜汤汁开胃，番茄红素遇油更好吸收。","heavy":true},
  {"id":"m37","name":"萝卜炖牛腩","type":"meat","spicy":false,"tags":["硬菜","适合老人","经典"],"time":90,"difficulty":"中等","ingredients":[{"name":"牛腩","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"白萝卜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"八角","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"老抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["牛腩切 3 厘米见方的块，冷水下锅加料酒 1 瓷勺，煮开撇净浮沫，捞出洗净。","锅中倒 1 瓷勺油，下姜片和 1 颗八角小火爆香，倒入牛腩中火煸炒 2 分钟出香。","加生抽 1 瓷勺、老抽半瓷勺翻炒上色，倒入热水没过牛腩两指。","大火烧开转小火，盖盖炖 1 小时，炖到筷子能轻松插透牛腩。","白萝卜去皮切滚刀块下锅，再炖 20 分钟至萝卜透明软糯。","加盐 2 克调味，开盖大火收浓汤汁，撒葱花出锅。"],"nutrition":{"kcal":300,"protein":22,"fat":21,"carbs":7,"calcium":25,"iron":2.8},"tip":"牛腩炖到筷子能插透再放萝卜，肉烂萝卜甜，老人也嚼得动。","heavy":true},
  {"id":"m38","name":"小炒黄牛肉","type":"meat","spicy":true,"tags":["湘味","下饭神器","高蛋白"],"time":15,"difficulty":"简单","ingredients":[{"name":"牛里脊","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"螺丝椒","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["牛里脊逆纹切薄片，加生抽 1 瓷勺、淀粉 1 小勺、几滴油抓匀腌 10 分钟。","螺丝椒斜切段，姜蒜切末，干辣椒剪小段。","热锅热油，下牛肉大火滑炒约 40 秒，表面刚变色约七成熟就盛出。","余油下姜蒜末和干辣椒爆香，倒螺丝椒段中大火炒 1 分钟，炒到表皮起一点虎皮。","回入牛肉，加蚝油 1 瓷勺，大火爆炒 30 秒立刻出锅，全程快炒牛肉才嫩。"],"nutrition":{"kcal":220,"protein":19,"fat":13,"carbs":6,"calcium":18,"iron":2.6},"tip":"牛肉逆着纹路切、大火快炒，口感才嫩，全程别超过2分钟。","heavy":true},
  {"id":"m39","name":"西兰花炒牛肉","type":"meat","spicy":false,"tags":["低脂","高蛋白","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"牛里脊","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"西兰花","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["牛里脊逆纹切薄片，加生抽 1 瓷勺、淀粉 1 小勺抓匀腌 10 分钟。","西兰花掰小朵洗净，沸水中加 1 克盐和几滴油，焯 1 分钟捞出沥干，焯过水既保色又缩短翻炒时间。","热锅热油，下蒜片爆香，倒牛肉片大火滑炒至完全变色。","下西兰花，加蚝油 1 瓷勺，大火翻炒 1 分钟。","尝味补少许盐，翻匀即可出锅。"],"nutrition":{"kcal":210,"protein":21,"fat":10,"carbs":9,"calcium":60,"iron":2.5},"tip":"西兰花维C含量高，能促进牛肉中铁的吸收，是黄金组合。"},
  {"id":"m40","name":"葱爆羊肉","type":"meat","spicy":false,"tags":["经典","高蛋白","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"羊肉片","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"小葱","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["羊肉片加料酒 1 瓷勺、生抽半瓷勺抓匀腌 5 分钟；小葱斜切段，葱白葱绿分开。","热锅倒 1 瓷勺油烧到微微冒烟，下姜丝蒜片和葱白爆香。","倒入羊肉片大火快炒约 1 分钟，炒到变色出香。","下葱绿翻炒两下，沿锅边烹几滴香醋，去膻又提香。","淋几滴香油，大火翻匀立刻出锅，久炒羊肉会出水变老。"],"nutrition":{"kcal":270,"protein":21,"fat":19,"carbs":4,"calcium":25,"iron":2.5},"tip":"羊肉温补铁含量高，秋冬吃很合适，大火快炒锁住嫩度。","heavy":true},
  {"id":"m41","name":"胡萝卜炖羊肉","type":"meat","spicy":false,"tags":["适合老人","硬菜","补铁"],"time":80,"difficulty":"中等","ingredients":[{"name":"羊腿肉","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"胡萝卜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"八角","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["羊腿肉切块冷水下锅，加料酒 1 瓷勺焯水，煮开撇净浮沫，捞出洗净。","锅中倒 1 瓷勺油，下姜片和 1 颗八角小火炒香，倒羊肉块中火煸炒 2 分钟。","加生抽 1 瓷勺炒匀上色，倒入热水没过羊肉两指。","大火烧开转小火，盖盖炖 50 分钟至羊肉软烂。","胡萝卜切滚刀块下锅，再炖 15 分钟到筷子轻松扎透。","加盐 2 克调味，撒葱花出锅。"],"nutrition":{"kcal":260,"protein":20,"fat":17,"carbs":8,"calcium":25,"iron":2.8},"tip":"胡萝卜的胡萝卜素是脂溶性的，和羊肉同炖吸收率更高。","heavy":true},
  {"id":"m42","name":"啤酒卤蛋","type":"meat","spicy":false,"tags":["小红书爆款","成本超低","儿童友好"],"time":35,"difficulty":"简单","ingredients":[{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"啤酒","amount":1,"unit":"个","category":"米面粮油"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"老抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"冰糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"八角","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["鸡蛋冷水下锅，水开后煮 8 分钟，捞出过凉水剥壳，蛋身浅划几刀更入味。","整罐啤酒倒入小锅，加生抽 2 瓷勺、老抽半瓷勺、冰糖 5 克、1 颗八角和姜片。","大火煮开转小火，放入鸡蛋卤 15 分钟，中途翻面两次让颜色均匀。","关火后让蛋继续泡在卤汁里，至少泡 2 小时，隔夜风味最佳。"],"nutrition":{"kcal":190,"protein":13,"fat":11,"carbs":8,"calcium":55,"iron":2},"tip":"啤酒中酒精煮制时基本挥发，卤蛋当早餐加蛋白质很方便。"},
  {"id":"m43","name":"丝瓜炒蛋","type":"meat","spicy":false,"tags":["家常","快手","适合老人"],"time":12,"difficulty":"简单","ingredients":[{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"丝瓜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["丝瓜削皮切滚刀块；鸡蛋加 1 克盐打散。","热锅倒 1 瓷勺油，倒入蛋液中火炒到刚刚凝固，铲成大块盛出，别炒老。","余油下蒜片爆香，倒丝瓜中火炒 2～3 分钟，炒到丝瓜出汁变软。","回入鸡蛋块，加盐 1 克翻匀，让蛋块吸饱丝瓜的清甜汤汁即可出锅。"],"nutrition":{"kcal":210,"protein":14,"fat":15,"carbs":6,"calcium":60,"iron":2},"tip":"丝瓜水分足热量低，配鸡蛋清爽又有蛋白质，夏天首选。"},
  {"id":"m44","name":"凉拌皮蛋豆腐","type":"meat","spicy":false,"tags":["快手","成本超低","家常"],"time":8,"difficulty":"简单","ingredients":[{"name":"皮蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"嫩豆腐","amount":200,"unit":"g","category":"奶品豆制品"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["嫩豆腐倒扣入盘，切成麻将块，保持形状不散。","皮蛋剥壳，刀上蘸点清水切成 6 瓣不粘刀，围着豆腐摆一圈。","小碗调料汁：生抽 1 瓷勺、香醋半瓷勺、白糖 1 小撮、香油几滴，加蒜末搅匀。","料汁淋在豆腐和皮蛋上，撒葱花，吃前拌开即可，全程不用开火。"],"nutrition":{"kcal":200,"protein":14,"fat":13,"carbs":6,"calcium":130,"iron":2.5},"tip":"免开火凉菜，豆腐补钙皮蛋提味，夏天没胃口时特别开胃。"},
  {"id":"m45","name":"虎皮红烧鹌鹑蛋","type":"meat","spicy":false,"tags":["小红书爆款","儿童最爱","下饭"],"time":25,"difficulty":"简单","ingredients":[{"name":"鹌鹑蛋","amount":10,"unit":"个","category":"肉禽蛋"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"老抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"白糖","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["鹌鹑蛋冷水下锅煮 5 分钟，过凉水剥壳，用厨房纸擦干表面水分，下锅才不溅油。","锅中倒 1 瓷勺油，小火把鹌鹑蛋煎到表皮金黄起皱，也就是虎皮。","下蒜末炒香，加生抽 1 瓷勺、老抽几滴、白糖 1 小撮和小半碗热水烧开。","中火煮 3 分钟让蛋入味，再转大火收汁，收到浓稠能裹住蛋身。","撒葱花出锅。"],"nutrition":{"kcal":230,"protein":13,"fat":17,"carbs":7,"calcium":50,"iron":3.2},"tip":"鹌鹑蛋个头小好入口，铁和卵磷脂丰富，很适合孩子加餐。"},
  {"id":"m46","name":"肉末烧豆腐","type":"meat","spicy":false,"tags":["下饭","家常","成本超低"],"time":20,"difficulty":"简单","ingredients":[{"name":"老豆腐","amount":200,"unit":"g","category":"奶品豆制品"},{"name":"猪肉末","amount":40,"unit":"g","category":"肉禽蛋"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["老豆腐切 2 厘米方块；锅中倒 1 瓷勺油，中火把豆腐煎到两面金黄盛出，煎过的豆腐烧不碎。","余油下肉末炒散至变色，加蒜末炒香。","加生抽 1 瓷勺、蚝油半瓷勺和半碗热水烧开，放入豆腐。","中小火焖 5 分钟让豆腐入味，轻轻推动锅子别用铲子翻。","淀粉 1 小勺加 2 瓷勺清水调开，倒入勾薄芡，汤汁浓稠发亮后撒葱花出锅。"],"nutrition":{"kcal":260,"protein":19,"fat":18,"carbs":6,"calcium":250,"iron":2.8},"tip":"老豆腐钙含量是嫩豆腐的两倍多，加少量肉末鲜味翻倍。"},
  {"id":"m47","name":"千张炒肉丝","type":"meat","spicy":false,"tags":["高蛋白","下饭","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"千张","amount":100,"unit":"g","category":"奶品豆制品"},{"name":"猪里脊肉","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"青椒（菜椒不辣）","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"蚝油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"玉米淀粉","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["千张切细丝，开水烫 30 秒去豆腥味，捞出沥干；里脊切细丝。","肉丝加生抽半瓷勺、淀粉 1 小勺抓匀上浆，腌 5 分钟。","热锅热油，下肉丝中大火滑炒至变色盛出。","余油下蒜片和青椒丝炒香，倒千张丝大火翻炒 1 分钟。","回入肉丝，加生抽半瓷勺、蚝油半瓷勺，翻炒均匀出锅。"],"nutrition":{"kcal":300,"protein":28,"fat":18,"carbs":6,"calcium":280,"iron":3.5},"tip":"千张是豆制品中的蛋白钙双料冠军，一盘顶半杯牛奶的钙。"},
  {"id":"m48","name":"手撕包菜炒五花肉","type":"meat","spicy":false,"tags":["下饭","成本超低","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"五花肉","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"包菜","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"生抽","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"香醋","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食盐","pantry":true,"amount":0,"unit":"适量","category":"调味干货"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["包菜手撕成大片去掉硬梗，洗净后甩干水分，带水下锅炒不出锅气。","五花肉切薄片，锅里滴几滴油，中小火把五花肉煸 2 分钟，煸出油脂、边缘微焦。","下蒜片和干辣椒段爆香。","倒入包菜转大火猛炒 1 分钟，沿锅边烹半瓷勺香醋激出香气。","加生抽 1 瓷勺、盐 1 克，炒到包菜断生还带脆劲，立刻出锅。"],"nutrition":{"kcal":240,"protein":10,"fat":19,"carbs":9,"calcium":55,"iron":1.2},"tip":"用五花肉自身油脂炒菜可少放油，包菜断生就出锅更爽脆。"},
  {"id":"m49","name":"午餐肉厚蛋烧","type":"meat","spicy":false,"tags":["儿童最爱","快手","小红书爆款"],"time":12,"difficulty":"简单","ingredients":[{"name":"午餐肉","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","pantry":true,"amount":0,"unit":"适量","category":"调味干货"}],"steps":["午餐肉切小丁；鸡蛋加葱花打散，午餐肉本身够咸，蛋液里不用再加盐。","平底锅刷薄薄一层油，小火倒入一半蛋液，均匀撒上午餐肉丁。","蛋液半凝固时用铲子从一端卷起，推到锅边。","倒入剩余蛋液，让它连上蛋卷底部，半凝固后接着卷起。","小火把蛋卷各面轻煎 30 秒定型，取出稍凉再切段，切面更整齐。"],"nutrition":{"kcal":300,"protein":17,"fat":24,"carbs":4,"calcium":60,"iron":2.2},"tip":"午餐肉钠和脂肪偏高，蛋液里不用再加盐，偶尔解馋即可。"},
  {"id":"m50","name":"柠檬手撕鸡","type":"meat","spicy":false,"tags":["小红书爆款","高蛋白","低脂"],"time":25,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"柠檬","amount":1,"unit":"个","category":"蔬菜水果"},{"name":"黄瓜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡腿肉冷水下锅，放姜片和葱结，大火煮开撇净浮沫，转中小火煮 15 分钟，筷子扎入没有血水渗出就熟了。","捞出立刻过凉水，肉质更紧实，放凉后去皮手撕成粗丝。","黄瓜拍裂切段铺盘底，鸡丝盖在上面。","柠檬半个挤汁、半个切薄片，与蒜末、生抽 1 瓷勺、香醋半瓷勺、白糖 1 小撮、香油几滴调成料汁。","料汁淋在鸡丝上抓拌均匀，撒葱花，冷藏 10 分钟更入味。"],"nutrition":{"kcal":245,"protein":27,"fat":12,"carbs":6,"calcium":30,"iron":1.4},"tip":"去皮鸡腿肉脂肪减半，柠檬维C还能促进铁吸收，减脂期也能放心吃。","heavy":true},
  {"id":"m51","name":"蒜香黄油虾","type":"meat","spicy":false,"tags":["小红书爆款","高蛋白","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"基围虾","amount":200,"unit":"g","category":"水产海鲜"},{"name":"黄油","amount":10,"unit":"g","category":"奶品豆制品"},{"name":"蒜","amount":20,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["基围虾剪去虾须虾枪，开背挑出虾线，加料酒 1 瓷勺腌 5 分钟，再用厨房纸吸干水分。","平底锅小火融化黄油，下蒜末慢慢炒出香味，注意别炒糊发苦。","转中火下虾，一面煎约 2 分钟至变红，翻面再煎 1 分钟，虾身红亮弯曲就是熟了。","沿锅边淋生抽半瓷勺，撒黑胡椒和葱花，翻匀出锅。"],"nutrition":{"kcal":230,"protein":28,"fat":11,"carbs":4,"calcium":90,"iron":1.8},"tip":"虾是优质蛋白低脂代表，黄油只需10克提香，孩子老人都爱吃。","heavy":true},
  {"id":"m52","name":"香煎三文鱼","type":"meat","spicy":false,"tags":["DHA","无刺","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"三文鱼","amount":130,"unit":"g","category":"水产海鲜"},{"name":"西兰花","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"柠檬","amount":1,"unit":"个","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["三文鱼用厨房纸彻底擦干，两面抹约 1 克盐和适量黑胡椒，腌 10 分钟。","西兰花掰小朵，沸水焯 1 分钟捞出沥干，围在盘边摆好。","平底锅倒几滴油中火烧热，鱼皮朝下放入，煎 3 分钟不要翻动，把鱼皮煎脆。","翻面再煎 2 分钟，从侧面看鱼肉整体变浅粉色就熟了，别煎过头发柴。","装盘挤上柠檬汁，配西兰花趁热吃。"],"nutrition":{"kcal":290,"protein":27,"fat":18,"carbs":5,"calcium":50,"iron":1.2},"tip":"三文鱼DHA含量高且完全无刺，是给孩子补脑最省心的鱼，每周吃1-2次。","heavy":true},
  {"id":"m53","name":"清蒸黄花鱼","type":"meat","spicy":false,"tags":["DHA","低脂","家常"],"time":20,"difficulty":"简单","ingredients":[{"name":"黄花鱼","amount":300,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["黄花鱼收拾干净，两面各划两刀，抹料酒 1 瓷勺，鱼肚塞姜片葱段，腌 10 分钟去腥。","蒸锅水完全烧开后再放鱼，大火蒸 8 分钟，筷子能轻松插入鱼背最厚处即熟。","取出倒掉盘中腥水，夹走姜葱，铺上新切的细葱丝。","蒸鱼豉油 1 瓷勺沿盘边淋入，别直接浇在鱼身上，保持鱼肉清爽。","烧 1 瓷勺热油至微微冒烟，浇在葱丝上激出香味即可。"],"nutrition":{"kcal":210,"protein":28,"fat":9,"carbs":2,"calcium":55,"iron":1},"tip":"黄花鱼刺少肉嫩富含DHA，给孩子吃时选中段大块肉，更放心。","heavy":true},
  {"id":"m54","name":"鲫鱼豆腐汤","type":"soup","spicy":false,"tags":["适合老人","高蛋白","家常"],"time":30,"difficulty":"中等","ingredients":[{"name":"鲫鱼","amount":250,"unit":"g","category":"水产海鲜"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鲫鱼收拾干净，用厨房纸把鱼身内外彻底擦干，煎的时候才不溅油不粘锅。","热锅倒 1 瓷勺油，中火把鱼两面各煎 2 分钟，煎到微黄定型。","一次性加入开水没过鱼身，放姜片、料酒 1 瓷勺，保持大火滚煮 10 分钟，汤才能煮成奶白色。","下嫩豆腐块，转中火再煮 8 分钟。","加盐 2 克调味，撒葱花出锅。"],"nutrition":{"kcal":250,"protein":26,"fat":14,"carbs":4,"calcium":180,"iron":1.8},"tip":"鱼加豆腐钙和蛋白互补，汤鲜刺多，给孩子喝汤吃豆腐即可。"},
  {"id":"m55","name":"蛤蜊蒸蛋","type":"meat","spicy":false,"tags":["儿童最爱","高蛋白","低脂"],"time":20,"difficulty":"简单","ingredients":[{"name":"蛤蜊","amount":150,"unit":"g","category":"水产海鲜"},{"name":"鸡蛋","amount":2,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["蛤蜊提前用盐水浸泡 2 小时充分吐沙，搓洗干净。","锅中加水和料酒 1 瓷勺烧开，下蛤蜊煮到开口立即捞出摆入深盘，煮蛤蜊的汤留用。","蛤蜊汤放至温热并滤净杂质，按汤 1.5 份、蛋液 1 份的比例和打散的鸡蛋混合。","蛋液过筛倒入盘中，盖上保鲜膜扎几个小孔，蒸出来才光滑没蜂窝。","蒸锅水开后转中火蒸 10 分钟，晃动盘子蛋面不再颤动就熟了。","出锅淋几滴蒸鱼豉油和香油，撒葱花即可。"],"nutrition":{"kcal":195,"protein":20,"fat":10,"carbs":5,"calcium":100,"iron":5},"tip":"蛤蜊含铁含锌高，配上嫩滑蒸蛋，是给孩子补铁补锌的一流搭配。"},
  {"id":"m56","name":"辣炒蛤蜊","type":"meat","spicy":true,"tags":["下饭神器","快手","成本超低"],"time":15,"difficulty":"简单","ingredients":[{"name":"蛤蜊","amount":350,"unit":"g","category":"水产海鲜"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"豆瓣酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["蛤蜊用盐水浸泡 2 小时充分吐沙，搓洗干净沥水。","热锅倒 1 瓷勺油，下蒜片姜丝、干辣椒段和豆瓣酱 1 小勺，小火炒出红油。","转大火倒入蛤蜊翻炒，烹料酒 1 瓷勺，加白糖 1 小撮提鲜，豆瓣酱够咸不必再加盐。","盖盖焖 1 分钟，再翻炒到蛤蜊全部开口，没开口的挑出来别吃。","撒葱段翻匀立刻出锅，久炒蛤蜊肉会缩老。"],"nutrition":{"kcal":185,"protein":19,"fat":8,"carbs":8,"calcium":130,"iron":7},"tip":"蛤蜊热量极低铁含量高，大火快炒开口即出锅，久炒肉会变老。","heavy":true},
  {"id":"m57","name":"白灼基围虾","type":"meat","spicy":false,"tags":["粤式","低脂","宴客拿得出手"],"time":10,"difficulty":"简单","ingredients":[{"name":"基围虾","amount":250,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["基围虾剪去虾须，冲洗干净沥水。","锅中烧开足量清水，放姜片、葱结和料酒 1 瓷勺去腥。","下虾大火煮约 2 分钟，虾身变红弯成 C 形立即捞出，煮过头肉就柴了。","捞出过一遍冰水或凉开水，虾肉更紧弹，沥干摆盘。","姜切细丝，加生抽 1 瓷勺、香油几滴调成蘸汁，剥壳蘸着吃。"],"nutrition":{"kcal":190,"protein":30,"fat":5,"carbs":3,"calcium":110,"iron":2},"tip":"白灼最大程度保留虾的优质蛋白和鲜味，几乎零额外油脂，减脂首选。","heavy":true},
  {"id":"m58","name":"番茄龙利鱼","type":"meat","spicy":false,"tags":["儿童最爱","无刺","下饭"],"time":20,"difficulty":"简单","ingredients":[{"name":"龙利鱼柳","amount":150,"unit":"g","category":"水产海鲜"},{"name":"番茄","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"番茄酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["龙利鱼柳解冻擦干，切 3 厘米的块，加料酒 1 瓷勺、盐 1 克、淀粉 1 小勺抓匀腌 10 分钟。","番茄顶部划十字用开水烫后去皮，切小丁。","热锅倒 1 瓷勺油，下蒜末爆香，倒番茄丁中火炒 3 分钟炒出沙。","加番茄酱 1 瓷勺和一小碗热水煮开，轻轻放入鱼块。","中火煮 4 分钟至鱼肉全部变白，尽量少翻动以免碎。","加盐 1 克、白糖 1 小撮调味，撒葱花出锅。"],"nutrition":{"kcal":205,"protein":24,"fat":7,"carbs":12,"calcium":40,"iron":1.2},"tip":"龙利鱼完全无刺无腥味，酸甜番茄汤汁拌饭，挑食孩子也能吃一大碗。","heavy":true},
  {"id":"m59","name":"干煎带鱼","type":"meat","spicy":false,"tags":["经典","家常","下饭"],"time":20,"difficulty":"简单","ingredients":[{"name":"带鱼","amount":200,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"花椒粉","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["带鱼段去净内脏和腹内黑膜，用姜片、料酒 1 瓷勺、盐 2 克抓匀腌 15 分钟。","用厨房纸把带鱼彻底擦干，两面薄薄拍一层淀粉，煎时不溅油、鱼皮不破。","平底锅倒 2 瓷勺油烧热，转中小火下带鱼，一面煎 3 分钟定型后再翻面。","另一面再煎 3 分钟，煎到两面金黄酥脆。","出锅趁热撒少许盐和花椒粉即可。"],"nutrition":{"kcal":260,"protein":24,"fat":16,"carbs":6,"calcium":40,"iron":1.5},"tip":"带鱼DHA和不饱和脂肪酸丰富，中间只有一根大骨，给孩子挑刺很方便。","heavy":true},
  {"id":"m60","name":"红烧鸡翅","type":"meat","spicy":false,"tags":["儿童最爱","下饭","家常"],"time":25,"difficulty":"简单","ingredients":[{"name":"鸡翅中","amount":200,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"冰糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"八角","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡翅中两面各划一刀方便入味，冷水下锅焯水，煮开撇沫捞出擦干。","锅中放几滴油和冰糖 8 克，小火慢慢炒到冰糖融化、冒小泡呈琥珀色。","立刻下鸡翅翻炒，让每只都裹上糖色。","加姜片、1 颗八角，烹料酒 1 瓷勺，再加生抽 1 瓷勺、老抽几滴和热水没过鸡翅。","中火盖盖焖 15 分钟，开盖转大火收汁，收到汤汁浓稠发亮。","撒葱花出锅。"],"nutrition":{"kcal":300,"protein":25,"fat":19,"carbs":8,"calcium":15,"iron":1.3},"tip":"鸡翅蛋白质优质易嚼，收汁前撇去浮油可减少三分之一脂肪摄入。","heavy":true},
  {"id":"m61","name":"黑椒煎鸡胸","type":"meat","spicy":false,"tags":["低脂","高蛋白","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"鸡胸肉","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"西兰花","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡胸从侧面片成两大片，用刀背把两面拍松，纤维断了才不柴。","加料酒 1 瓷勺、生抽 1 瓷勺、适量黑胡椒抓匀腌 15 分钟。","西兰花掰小朵沸水焯 1 分钟，捞出垫在盘底。","平底锅倒几滴油中火烧热，下鸡胸每面煎 3 分钟至金黄。","加蒜末再煎 1 分钟出蒜香，淋蚝油半瓷勺和 2 瓷勺热水，翻面裹匀酱汁。","取出稍凉切条，摆在西兰花上。"],"nutrition":{"kcal":220,"protein":32,"fat":7,"carbs":8,"calcium":45,"iron":1.5},"tip":"鸡胸肉是性价比最高的低脂高蛋白食材，拍松再腌就不柴。","heavy":true},
  {"id":"m62","name":"酱香焖鸭腿","type":"meat","spicy":false,"tags":["硬菜","下饭","宴客拿得出手"],"time":45,"difficulty":"中等","ingredients":[{"name":"鸭腿","amount":220,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"冰糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"八角","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸭腿冷水下锅，煮开撇沫再焯 3 分钟去腥，捞出擦干。","不放油，鸭腿皮朝下入锅，中小火干煸 3～4 分钟逼出鸭油，两面煎到微黄。","下姜片蒜瓣、1 颗八角和冰糖 5 克，借着鸭油炒出香味。","烹料酒 1 瓷勺，加生抽 1 瓷勺、老抽半瓷勺，再加热水没过鸭腿一半。","盖盖小火焖 35 分钟，中途翻面一次，焖到筷子能轻松扎透。","开盖大火收浓汤汁，撒葱花出锅。"],"nutrition":{"kcal":310,"protein":26,"fat":20,"carbs":7,"calcium":15,"iron":3},"tip":"鸭肉铁含量高于鸡肉，干煸逼出皮下油脂后再焖，更香也更低脂。","heavy":true},
  {"id":"m63","name":"韭菜炒鱿鱼","type":"meat","spicy":false,"tags":["快手","高蛋白","家常"],"time":15,"difficulty":"简单","ingredients":[{"name":"鱿鱼","amount":180,"unit":"g","category":"水产海鲜"},{"name":"韭菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鱿鱼撕去外膜，内侧打十字花刀再切块；韭菜切段，梗和叶分开放。","沸水加料酒 1 瓷勺，下鱿鱼烫 10 秒，花刀卷起立即捞出沥干，焯烫定型又去腥。","热锅热油，下姜丝蒜片爆香。","转大火倒入鱿鱼和韭菜梗，猛炒 30 秒。","下韭菜叶，加生抽半瓷勺、蚝油半瓷勺，翻匀立刻出锅，全程不超过 2 分钟鱿鱼才嫩。"],"nutrition":{"kcal":190,"protein":26,"fat":6,"carbs":8,"calcium":70,"iron":1.6},"tip":"鱿鱼高蛋白低脂肪还富含牛磺酸，焯烫加爆炒全程别超过2分钟才嫩。"},
  {"id":"m64","name":"蒜蓉粉丝蒸扇贝","type":"meat","spicy":false,"tags":["宴客拿得出手","小红书爆款","粤式"],"time":20,"difficulty":"中等","ingredients":[{"name":"扇贝","amount":4,"unit":"个","category":"水产海鲜"},{"name":"龙口粉丝","amount":30,"unit":"g","category":"米面粮油"},{"name":"蒜","amount":25,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["扇贝用刷子刷净外壳，撬开取肉，去掉黑色内脏和杂质，冲洗干净，壳留用。","粉丝温水泡 10 分钟至软，剪短垫在每个壳里，贝肉放回粉丝上。","锅中倒 1 瓷勺油，小火把一半蒜末炸至微黄，关火拌入另一半生蒜末、蒸鱼豉油 1 瓷勺和料酒几滴，调成金银蒜蓉酱。","蒜蓉酱分铺在每个贝肉上，蒸锅水开后大火蒸 6 分钟。","出锅撒葱花，再烧 1 瓷勺热油浇在蒜蓉上激出香味即可。"],"nutrition":{"kcal":200,"protein":18,"fat":7,"carbs":17,"calcium":90,"iron":2.2},"tip":"扇贝柱是优质蛋白，锌含量突出，蒸制做法保留鲜味又不额外增脂。","heavy":true},
  {"id":"m65","name":"土豆焖鸡腿","type":"meat","spicy":false,"tags":["一锅出","下饭","家常"],"time":30,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"土豆","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡腿肉切块冷水下锅焯水，煮开撇沫捞出；土豆、胡萝卜削皮切滚刀块。","热锅倒 1 瓷勺油，下姜片蒜瓣爆香，倒鸡块中火炒 2 分钟至表面微黄。","烹料酒 1 瓷勺，加生抽 1 瓷勺、老抽几滴、白糖 1 小撮，翻炒上色。","加热水没过食材，放入土豆和胡萝卜块。","盖盖中小火焖 15 分钟，土豆用筷子能扎透后开盖大火收汁，汤汁浓稠裹匀即可。"],"nutrition":{"kcal":290,"protein":24,"fat":13,"carbs":22,"calcium":25,"iron":1.6},"tip":"一锅出有荤有素有主食，土豆吸满汤汁，晚餐可适当减少米饭量。","heavy":true},
  {"id":"m66","name":"西兰花炒虾仁","type":"meat","spicy":false,"tags":["低脂","高蛋白","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"冷冻虾仁","amount":150,"unit":"g","category":"水产海鲜"},{"name":"西兰花","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["虾仁解冻后用厨房纸吸干水分，加料酒半瓷勺、淀粉 1 小勺抓匀腌 10 分钟。","西兰花掰小朵、胡萝卜切薄片，沸水加 1 克盐焯 1 分钟捞出沥干。","热锅倒 1 瓷勺油，下蒜片爆香，倒虾仁中大火炒到全部变红卷曲。","倒入西兰花和胡萝卜，加蚝油半瓷勺、盐 1 克。","大火翻炒 1 分钟，均匀裹上味道即可出锅。"],"nutrition":{"kcal":185,"protein":25,"fat":6,"carbs":10,"calcium":100,"iron":1.8},"tip":"虾仁加西兰花是经典减脂组合，蛋白质高热量低，晚餐吃也无负担。"},
  {"id":"m67","name":"油焖大虾","type":"meat","spicy":false,"tags":["经典","宴客拿得出手","儿童最爱"],"time":20,"difficulty":"中等","ingredients":[{"name":"基围虾","amount":250,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"番茄酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["基围虾剪去虾须虾枪，开背挑出虾线，用厨房纸擦干水分。","锅中倒 2 瓷勺油烧热，下虾中火煎到两面变红，用铲子轻压虾头煸出红色虾油。","下姜末炒香，烹料酒 1 瓷勺，加番茄酱 1 瓷勺、生抽 1 瓷勺、白糖 1 小勺和小半碗热水。","中火焖 3 分钟让虾入味，再转大火把汤汁收浓，裹在虾身上红亮诱人。","撒葱花出锅。"],"nutrition":{"kcal":235,"protein":28,"fat":10,"carbs":9,"calcium":105,"iron":2},"tip":"虾头煸出的虾油富含虾青素，酸甜汁裹住虾肉，孩子剥壳吃得停不下来。","heavy":true},
  {"id":"m68","name":"豆豉蒸鸡","type":"meat","spicy":false,"tags":["粤式","低脂","适合老人"],"time":25,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":180,"unit":"g","category":"肉禽蛋"},{"name":"干香菇","amount":10,"unit":"g","category":"调味干货"},{"name":"姜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"豆豉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡腿肉去骨切块；干香菇温水泡发 30 分钟，挤干水分切片。","鸡块和香菇加剁碎的豆豉 1 瓷勺、姜丝、生抽 1 瓷勺、料酒半瓷勺、淀粉 1 小勺抓匀，腌 20 分钟入味。","平铺在深盘中，尽量摊开不叠放，受热才均匀。","蒸锅水开后放入，大火蒸 15 分钟，鸡肉熟透无血水即可。","出锅淋几滴香油，撒葱花即可。"],"nutrition":{"kcal":240,"protein":27,"fat":12,"carbs":6,"calcium":25,"iron":1.8},"tip":"蒸制不额外用油，鸡肉嫩滑豉香浓，牙口不好的老人也容易嚼。","heavy":true},
  {"id":"m69","name":"水煮龙利鱼片","type":"meat","spicy":true,"tags":["川味","下饭神器","无刺"],"time":25,"difficulty":"中等","ingredients":[{"name":"龙利鱼柳","amount":180,"unit":"g","category":"水产海鲜"},{"name":"绿豆芽","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"生菜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"干辣椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"花椒粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["龙利鱼柳斜刀切成约 0.5 厘米厚的片，加料酒 1 瓷勺、盐 1 克、玉米淀粉 1 瓷勺抓匀，腌 10 分钟锁住水分。","烧一锅开水，绿豆芽和生菜分别烫 30 秒至断生，捞出垫在大碗底。","锅中倒油 1 瓷勺，小火炒香豆瓣酱 1 瓷勺至出红油，加约 400 毫升热水煮开。","转中小火，逐片滑入鱼片，先别翻动，煮 2 分钟至鱼片变白卷边即熟。","连汤带鱼倒入碗中，表面铺蒜末、干辣椒段和花椒粉。","另起锅烧 1 瓷勺油至微微冒烟，趁热浇在蒜末辣椒上激出香味。"],"nutrition":{"kcal":230,"protein":25,"fat":11,"carbs":9,"calcium":60,"iron":1.6},"tip":"用无刺龙利鱼做水煮鱼不用担心卡刺，麻辣过瘾但记得少喝红油汤。","heavy":true},
  {"id":"m70","name":"冬瓜老鸭汤","type":"soup","spicy":false,"tags":["适合老人","低脂","家常"],"time":60,"difficulty":"简单","ingredients":[{"name":"鸭腿","amount":200,"unit":"g","category":"肉禽蛋"},{"name":"冬瓜","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸭腿斩成小块，冷水下锅，加料酒 1 瓷勺和两片姜，大火煮开撇净浮沫，再煮 2 分钟捞出用温水冲净，去腥更彻底。","鸭块放入汤锅，加剩余姜片和约 800 毫升热水，大火烧开后转小火加盖炖 40 分钟。","冬瓜去皮去瓤切成大块，下锅再炖 10 分钟，煮至冬瓜边缘透明变软。","用勺撇去表面浮油，加盐 2 克调味，撒上葱花即可。"],"nutrition":{"kcal":240,"protein":24,"fat":14,"carbs":5,"calcium":30,"iron":2.6},"tip":"鸭肉配冬瓜清润不腻，喝前撇净浮油，适合老人和夏天没胃口时。"},
  {"id":"m71","name":"凉拌鸡丝","type":"meat","spicy":false,"tags":["低脂","高蛋白","快手"],"time":20,"difficulty":"简单","ingredients":[{"name":"鸡胸肉","amount":130,"unit":"g","category":"肉禽蛋"},{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡胸肉冷水下锅，放入姜片，大火烧开后转小火煮 12 分钟，关火加盖再焖 5 分钟，鸡肉熟透又不柴。","捞出鸡胸放至不烫手，顺着纹路撕成细丝。","黄瓜、胡萝卜切细丝，和鸡丝一起放入大碗。","蒜末加生抽 1 瓷勺、香醋 1 瓷勺、白糖 1 小勺、香油几滴调成料汁。","料汁倒入碗中抓拌均匀，静置 5 分钟更入味。"],"nutrition":{"kcal":190,"protein":28,"fat":6,"carbs":8,"calcium":35,"iron":1.2},"tip":"水煮加焖的鸡胸不柴不腻，一盘热量不到200千卡，蛋白却近30克。"},
  {"id":"m72","name":"虾仁豆腐煲","type":"meat","spicy":false,"tags":["高蛋白","适合老人","一锅出"],"time":20,"difficulty":"简单","ingredients":[{"name":"冷冻虾仁","amount":100,"unit":"g","category":"水产海鲜"},{"name":"嫩豆腐","amount":200,"unit":"g","category":"奶品豆制品"},{"name":"金针菇","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["虾仁提前解冻，用厨房纸吸干水分；嫩豆腐切 2 厘米见方的块，金针菇去根撕开。","锅中倒油 1 瓷勺，中火爆香姜末，下虾仁炒 1 分钟至变红弯身。","加约 300 毫升热水煮开，轻轻放入豆腐和金针菇，中火煮 5 分钟。","加蚝油 1 瓷勺、生抽半瓷勺调味，轻推几下别把豆腐搅碎。","玉米淀粉 1 小勺加 2 瓷勺清水调开，淋入锅中勾薄芡，汤汁略浓后撒葱花出锅。"],"nutrition":{"kcal":210,"protein":24,"fat":9,"carbs":10,"calcium":200,"iron":2.5},"tip":"虾仁和豆腐双重优质蛋白，一煲补钙近200毫克，软嫩适合老人孩子。"},
  {"id":"m73","name":"宫保虾球","type":"meat","spicy":true,"tags":["川味","下饭神器","高蛋白"],"time":20,"difficulty":"中等","ingredients":[{"name":"冷冻虾仁","amount":150,"unit":"g","category":"水产海鲜"},{"name":"黄瓜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"花生米","amount":20,"unit":"g","category":"调味干货"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["虾仁解冻擦干，加料酒 1 瓷勺、玉米淀粉 1 小勺抓匀腌 10 分钟；黄瓜切小丁。","取小碗调宫保汁：生抽 1 瓷勺、香醋 1 瓷勺、白糖 1 小勺、玉米淀粉 1 小勺，加 2 瓷勺清水搅匀。","锅中少油小火把花生米炒 2 分钟至微黄出香，盛出放凉才会脆。","补 1 瓷勺油，小火爆香干辣椒段、蒜末和葱段，别炒糊发苦。","转大火下虾仁炒 1 分钟至变红卷曲，倒入黄瓜丁和料汁。","翻炒至酱汁起泡收浓裹匀，关火拌入花生米即可。"],"nutrition":{"kcal":260,"protein":26,"fat":12,"carbs":14,"calcium":90,"iron":2},"tip":"用虾仁替换鸡丁脂肪更低，酸甜微辣超下饭，花生最后放才够脆。","heavy":true},
  {"id":"m74","name":"山药炖鸡汤","type":"soup","spicy":false,"tags":["适合老人","家常","高蛋白"],"time":50,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":180,"unit":"g","category":"肉禽蛋"},{"name":"山药","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡腿肉切块冷水下锅，加料酒 1 瓷勺，大火煮开撇净浮沫，捞出用温水冲净。","鸡块与姜片放入汤锅，加约 800 毫升热水，大火烧开转小火加盖炖 30 分钟。","山药去皮切滚刀块（怕手痒可戴手套操作），胡萝卜切滚刀块，一起下锅再炖 15 分钟至山药软糯。","加盐 2 克调味，撒葱花出锅。"],"nutrition":{"kcal":265,"protein":25,"fat":12,"carbs":18,"calcium":30,"iron":1.5},"tip":"山药健脾易消化，和鸡汤同炖汤清味鲜，适合老人孩子换季喝。"},
  {"id":"m75","name":"杏鲍菇炒鸡丁","type":"meat","spicy":false,"tags":["家常","快手","成本超低"],"time":15,"difficulty":"简单","ingredients":[{"name":"鸡胸肉","amount":130,"unit":"g","category":"肉禽蛋"},{"name":"杏鲍菇","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"青椒（菜椒不辣）","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡胸肉切 1.5 厘米的小丁，加料酒 1 瓷勺、生抽半瓷勺、玉米淀粉 1 小勺抓匀，腌 10 分钟锁水。","杏鲍菇切丁，不放油中火干煸 2 分钟，煸出水分表面微黄后盛出，口感更像肉。","锅中倒油 1 瓷勺，中火爆香蒜末，下鸡丁滑炒 2 分钟至完全变白。","倒回杏鲍菇，加青椒丁，转大火翻炒 1 分钟。","加蚝油 1 瓷勺翻匀，尝味后按需补少许盐即可出锅。"],"nutrition":{"kcal":210,"protein":28,"fat":7,"carbs":12,"calcium":20,"iron":1.3},"tip":"杏鲍菇口感像肉、膳食纤维高，和鸡丁同炒荤素平衡，成本不到十元。"},
  {"id":"v18","name":"清炒菠菜","type":"veg","spicy":false,"tags":["绿叶菜","快手","成本超低"],"time":8,"difficulty":"简单","ingredients":[{"name":"菠菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["菠菜洗净切长段，沸水中焯 15 秒去掉草酸，捞出沥干。","热锅倒油 1 瓷勺，中火爆香蒜末。","倒入菠菜转大火快炒 30 秒，至叶片变软油亮。","加盐 2 克翻匀立即出锅，久炒会出水发黑。"],"nutrition":{"kcal":95,"protein":6,"fat":6,"carbs":8,"calcium":140,"iron":4.5},"tip":"菠菜先焯水去草酸，钙和铁更好吸收，大火快炒保住叶酸"},
  {"id":"v19","name":"姜汁菠菜","type":"veg","spicy":false,"tags":["凉拌","绿叶菜","低油"],"time":10,"difficulty":"简单","ingredients":[{"name":"菠菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["菠菜洗净不切，沸水焯 30 秒去草酸，捞出立刻过凉水，颜色更翠绿。","轻轻挤干水分，切成长段理顺装盘。","姜磨成细蓉，加生抽 1 瓷勺、香醋 1 瓷勺、盐 1 克和 1 瓷勺凉开水调成姜汁。","姜汁淋在菠菜上，点几滴香油，吃前拌匀即可。"],"nutrition":{"kcal":70,"protein":6,"fat":3,"carbs":8,"calcium":140,"iron":4.5},"tip":"凉拌少油更清爽，姜汁开胃暖胃，适合夏天没胃口时吃"},
  {"id":"v20","name":"蒜蓉空心菜","type":"veg","spicy":false,"tags":["绿叶菜","快手","时令"],"time":8,"difficulty":"简单","ingredients":[{"name":"空心菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["空心菜择洗干净，切成约 5 厘米的长段，梗和叶分开放。","热锅倒油 1 瓷勺，中火爆香一半蒜末。","转大火先下菜梗炒 30 秒，再下菜叶炒 30 秒至变软。","加盐 2 克和剩余的生蒜末快速翻匀出锅，蒜香更冲。"],"nutrition":{"kcal":90,"protein":5,"fat":6,"carbs":7,"calcium":180,"iron":2.5},"tip":"空心菜含钙量在绿叶菜里名列前茅，大火快炒口感最脆嫩"},
  {"id":"v21","name":"白灼芥蓝","type":"veg","spicy":false,"tags":["绿叶菜","补钙","低油"],"time":10,"difficulty":"简单","ingredients":[{"name":"芥蓝","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["芥蓝削去根部老皮，洗净沥干。","水烧开后加少许盐和几滴油，下芥蓝烫 1 分半至颜色翠绿发亮，捞出整齐摆盘。","蒸鱼豉油 1 瓷勺加 1 小撮白糖和 1 瓷勺热水调匀，淋在芥蓝上。","蒜末铺在芥蓝表面，烧 1 瓷勺热油至微冒烟浇上，激出蒜香即可。"],"nutrition":{"kcal":95,"protein":5,"fat":6,"carbs":8,"calcium":200,"iron":2},"tip":"芥蓝钙含量高且草酸低，是补钙性价比很高的深色蔬菜"},
  {"id":"v22","name":"蒜蓉苋菜","type":"veg","spicy":false,"tags":["绿叶菜","补钙","时令"],"time":8,"difficulty":"简单","ingredients":[{"name":"苋菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["苋菜择去老梗洗净，充分沥干水分。","热锅倒油 1 瓷勺，中火爆香蒜末。","下苋菜转大火翻炒 2 分钟，炒至叶片变软渗出红汤。","加盐 2 克翻匀出锅，红汤别倒掉，拌饭很香。"],"nutrition":{"kcal":85,"protein":6,"fat":6,"carbs":7,"calcium":280,"iron":5},"tip":"苋菜钙铁双高，红色汤汁拌饭孩子也爱吃，夏季应季更便宜"},
  {"id":"v23","name":"香菇青菜","type":"veg","spicy":false,"tags":["绿叶菜","下饭","适合老人"],"time":15,"difficulty":"简单","ingredients":[{"name":"上海青","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"干香菇","amount":8,"unit":"g","category":"调味干货"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["干香菇提前用温水泡发 30 分钟，挤干切片，泡菇水留着别倒。","上海青对半切开，沸水加几滴油焯 1 分钟，捞出沥干围盘摆好。","热锅倒油 1 瓷勺，中火爆香蒜末，下香菇片炒 1 分钟出香。","加半碗泡菇水和蚝油 1 瓷勺煮开，泡菇水提鲜。","玉米淀粉 1 小勺加 2 瓷勺清水调开，倒入勾薄芡，汤汁浓亮后浇在青菜上即可。"],"nutrition":{"kcal":100,"protein":5,"fat":6,"carbs":10,"calcium":150,"iron":2},"tip":"干香菇的鲜味素比鲜菇更浓，泡菇水别倒，用来做芡汁提鲜"},
  {"id":"v24","name":"韭菜炒香干","type":"veg","spicy":false,"tags":["植物蛋白","补钙","下饭"],"time":10,"difficulty":"简单","ingredients":[{"name":"韭菜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"香干","amount":100,"unit":"g","category":"奶品豆制品"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["韭菜洗净切 4 厘米长段，香干切条。","热锅倒油 1 瓷勺，中火下香干煸 2 分钟至表面微黄起泡。","加生抽 1 瓷勺炒匀上色，转大火下韭菜段。","快炒 30 秒至韭菜刚变软，加盐 1 克翻匀立即出锅，久炒会出水变塌。"],"nutrition":{"kcal":185,"protein":15,"fat":11,"carbs":8,"calcium":320,"iron":4},"tip":"香干补钙补蛋白，配深绿色韭菜，一道菜兼顾钙和膳食纤维"},
  {"id":"v25","name":"韭菜炒绿豆芽","type":"veg","spicy":false,"tags":["绿叶菜","成本超低","快手"],"time":8,"difficulty":"简单","ingredients":[{"name":"绿豆芽","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"韭菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["绿豆芽淘洗后充分沥干，韭菜洗净切段。","热锅倒油 1 瓷勺，大火下豆芽翻炒 1 分钟至微微变透。","沿锅边淋香醋半瓷勺，醋香保脆还护住维生素 C，随后下韭菜。","加盐 2 克快速翻匀，韭菜刚塌秧就出锅，全程大火才脆。"],"nutrition":{"kcal":85,"protein":5,"fat":5,"carbs":8,"calcium":70,"iron":1.8},"tip":"豆芽热量低水分足，全程大火快炒才脆，醋能保住维生素C"},
  {"id":"v26","name":"清炒菜心","type":"veg","spicy":false,"tags":["绿叶菜","快手","低油"],"time":8,"difficulty":"简单","ingredients":[{"name":"菜心","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["菜心洗净，粗梗斜刀切开，梗叶分开放，受热才均匀。","热锅倒油 1 瓷勺，中火爆香蒜片。","转大火先下菜梗炒 30 秒，再下菜叶。","加盐 2 克翻炒 30 秒，颜色翠绿断生立即出锅。"],"nutrition":{"kcal":85,"protein":4,"fat":6,"carbs":6,"calcium":120,"iron":1.5},"tip":"菜梗和菜叶分先后下锅，熟度一致，老人孩子都嚼得动"},
  {"id":"v27","name":"虾皮小白菜","type":"veg","spicy":false,"tags":["补钙","绿叶菜","成本超低"],"time":8,"difficulty":"简单","ingredients":[{"name":"小白菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"虾皮","amount":5,"unit":"g","category":"调味干货"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["小白菜洗净切段，虾皮用清水冲一下去浮尘。","热锅倒油 1 瓷勺，中火爆香蒜末和虾皮，虾皮出香即可。","转大火下小白菜翻炒 1 分钟至变软。","虾皮自带咸味，先尝一口再决定要不要补盐，翻匀出锅。"],"nutrition":{"kcal":80,"protein":6,"fat":5,"carbs":5,"calcium":260,"iron":2},"tip":"虾皮自带咸鲜和钙，盐要少放，这道菜是平价补钙组合"},
  {"id":"v28","name":"菠菜豆腐汤","type":"soup","spicy":false,"tags":["补钙","适合老人","低油"],"time":15,"difficulty":"简单","ingredients":[{"name":"菠菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["菠菜洗净，沸水焯 15 秒去草酸，捞出切段，这样不影响豆腐里钙的吸收。","嫩豆腐切小块，姜切细丝。","锅中加约 500 毫升水烧开，下姜丝和豆腐，中火煮 3 分钟。","放入菠菜再煮 30 秒，加盐 2 克，点几滴香油出锅。"],"nutrition":{"kcal":115,"protein":10,"fat":6,"carbs":6,"calcium":200,"iron":3},"tip":"菠菜先焯水去草酸，就不影响豆腐里钙的吸收，可放心同吃"},
  {"id":"v29","name":"小葱拌豆腐","type":"veg","spicy":false,"tags":["凉拌","补钙","快手"],"time":5,"difficulty":"简单","ingredients":[{"name":"嫩豆腐","amount":200,"unit":"g","category":"奶品豆制品"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"虾皮","amount":3,"unit":"g","category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["嫩豆腐用温开水轻轻冲一遍，切小块装盘，倒掉盘里多余的水。","小葱切碎；虾皮放干锅小火烘 1 分钟出香，鲜味更足。","葱花和虾皮撒在豆腐上，淋生抽 1 瓷勺和几滴香油。","吃前再轻轻拌匀即可，拌早了容易出水。"],"nutrition":{"kcal":145,"protein":11,"fat":9,"carbs":5,"calcium":180,"iron":2},"tip":"5分钟上桌的优质蛋白菜，加一撮烘香的虾皮鲜味翻倍"},
  {"id":"v30","name":"凉拌腐竹芹菜","type":"veg","spicy":false,"tags":["凉拌","植物蛋白","小红书爆款"],"time":20,"difficulty":"简单","ingredients":[{"name":"腐竹","amount":25,"unit":"g","category":"奶品豆制品"},{"name":"芹菜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["腐竹提前用温水泡 1 小时，泡到完全变软无硬芯，斜刀切段。","芹菜切段、胡萝卜切丝，与腐竹分别下沸水焯 1 分钟，捞出过凉水更爽脆。","蒜末加生抽 1 瓷勺、香醋 1 瓷勺、白糖 1 小勺、香油几滴调成料汁。","沥干的食材倒入料汁抓拌均匀，冷藏 10 分钟更入味。"],"nutrition":{"kcal":175,"protein":13,"fat":10,"carbs":9,"calcium":90,"iron":3},"tip":"腐竹是浓缩的大豆蛋白，一小把顶半块豆腐，凉拌低油更健康"},
  {"id":"v31","name":"青椒炒豆干","type":"veg","spicy":false,"tags":["植物蛋白","下饭","补钙"],"time":10,"difficulty":"简单","ingredients":[{"name":"香干","amount":120,"unit":"g","category":"奶品豆制品"},{"name":"青椒（菜椒不辣）","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["香干切片，青椒去籽切块。","热锅倒油 1 瓷勺，中火爆香蒜片，下香干煸 2 分钟至出焦边。","转大火下青椒翻炒 1 分钟至断生。","加生抽 1 瓷勺、盐 1 克炒匀出锅。"],"nutrition":{"kcal":195,"protein":17,"fat":12,"carbs":8,"calcium":350,"iron":4.5},"tip":"菜椒不辣维C高，配豆干蛋白钙都够，是素菜里的营养主力"},
  {"id":"v32","name":"素麻婆豆腐","type":"veg","spicy":true,"tags":["下饭","植物蛋白"],"time":15,"difficulty":"中等","ingredients":[{"name":"嫩豆腐","amount":250,"unit":"g","category":"奶品豆制品"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"花椒粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["嫩豆腐切 2 厘米方块，放入加了少许盐的沸水中焯 1 分钟，豆腐更紧实不易碎。","锅中倒油 1 瓷勺，小火炒香豆瓣酱 1 瓷勺和蒜末，慢慢炒出红油。","加半碗热水和生抽半瓷勺煮开，轻轻推入豆腐，中小火烧 3 分钟入味。","玉米淀粉 1 小勺加 2 瓷勺清水调开，分 2 次淋入勾芡，汤汁浓稠裹住豆腐。","撒花椒粉和葱花出锅，豆瓣酱偏咸，不用再加盐。"],"nutrition":{"kcal":190,"protein":13,"fat":12,"carbs":9,"calcium":190,"iron":3},"tip":"素版少了肉末但蛋白不缺，豆瓣酱偏咸，无需再额外加盐"},
  {"id":"v33","name":"凉拌莴笋丝","type":"veg","spicy":false,"tags":["凉拌","爽口","低油"],"time":10,"difficulty":"简单","ingredients":[{"name":"莴笋","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["莴笋去皮，切成均匀细丝。","加盐 2 克抓匀腌 5 分钟，杀出水分后轻轻挤干，口感更脆。","加蒜末、白糖 1 小勺、香醋 1 瓷勺、香油几滴拌匀。","装盘即食，冷藏 10 分钟后更冰脆爽口。"],"nutrition":{"kcal":55,"protein":2,"fat":3,"carbs":7,"calcium":40,"iron":1},"tip":"莴笋含钾高热量低，先盐腌挤水口感更脆，适合控体重人群"},
  {"id":"v34","name":"糖醋凉拌藕片","type":"veg","spicy":false,"tags":["凉拌","爽口","时令"],"time":15,"difficulty":"简单","ingredients":[{"name":"藕","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["藕去皮切薄片，清水里泡一泡冲去表面淀粉，不易发黑。","沸水下藕片焯 1 分钟至断生，捞出过凉水保脆。","香醋 1 瓷勺、白糖 1 瓷勺、生抽半瓷勺加蒜末调成糖醋汁。","沥干的藕片倒入料汁拌匀，撒葱花、点几滴香油即可。"],"nutrition":{"kcal":150,"protein":3,"fat":3,"carbs":30,"calcium":45,"iron":1.2},"tip":"藕淀粉含量高，这道菜可替代部分主食，吃了记得米饭减量"},
  {"id":"v35","name":"蒜泥秋葵","type":"veg","spicy":false,"tags":["凉拌","小红书爆款","低油"],"time":10,"difficulty":"简单","ingredients":[{"name":"秋葵","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["秋葵洗净先不去蒂，沸水加几滴油，整根焯 2 分钟至颜色翠绿，黏液营养不流失。","捞出过凉水，切去硬蒂，对半剖开摆盘。","蒜末加蒸鱼豉油 1 瓷勺、香油几滴和 1 瓷勺凉开水调成料汁。","料汁淋在秋葵上即可开吃。"],"nutrition":{"kcal":75,"protein":4,"fat":4,"carbs":9,"calcium":90,"iron":1.2},"tip":"秋葵的黏液是可溶性膳食纤维，整根焯熟再切才不流失"},
  {"id":"v36","name":"白灼芦笋","type":"veg","spicy":false,"tags":["小红书爆款","低油","快手"],"time":8,"difficulty":"简单","ingredients":[{"name":"芦笋","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["芦笋切去老根，根部老皮用削皮刀削掉，口感不柴。","水烧开加少许盐和几滴油，下芦笋烫 1 分半至翠绿发亮，捞出摆盘。","趁热淋上蒸鱼豉油 1 瓷勺，蒜末铺在芦笋中段。","烧 1 瓷勺热油至微冒烟，浇在蒜末上激出香味即可。"],"nutrition":{"kcal":70,"protein":4,"fat":5,"carbs":6,"calcium":25,"iron":1.5},"tip":"芦笋叶酸含量突出，备孕和孕期家庭可常做，白灼最保营养"},
  {"id":"v37","name":"干锅花菜","type":"veg","spicy":true,"tags":["下饭","成本超低"],"time":15,"difficulty":"中等","ingredients":[{"name":"花菜","amount":300,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"豆豉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["花菜手掰成小朵，洗净后务必沥干，下锅煸时才不溅油。","不放油，中火干煸花菜 3 分钟，至边缘微焦出香后盛出。","锅中倒油 1 瓷勺，小火爆香蒜片、干辣椒段和豆豉。","倒回花菜转大火，加生抽 1 瓷勺、白糖 1 小撮翻炒 1 分钟入味。","撒葱段翻匀出锅。"],"nutrition":{"kcal":130,"protein":5,"fat":8,"carbs":12,"calcium":60,"iron":1.5},"tip":"先干煸出焦香就能少放油，比饭店干锅版热量低一半"},
  {"id":"v38","name":"上汤娃娃菜","type":"veg","spicy":false,"tags":["适合老人","补钙","低油"],"time":15,"difficulty":"简单","ingredients":[{"name":"娃娃菜","amount":300,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":20,"unit":"g","category":"蔬菜水果"},{"name":"虾皮","amount":5,"unit":"g","category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["娃娃菜洗净，竖着切成条。","锅中倒油 1 瓷勺，小火把整瓣蒜煎 2 分钟至金黄，这是汤色奶白的关键。","加约 500 毫升开水和虾皮，大火煮 2 分钟至汤色发白。","下娃娃菜转中火煮 3 分钟至软，加盐 1 克调味，连汤带菜上桌。"],"nutrition":{"kcal":95,"protein":5,"fat":6,"carbs":8,"calcium":150,"iron":1.2},"tip":"娃娃菜软嫩带甜，连汤带菜适合老人，虾皮提鲜还补钙"},
  {"id":"v39","name":"荷兰豆炒口蘑","type":"veg","spicy":false,"tags":["快手","爽口","低油"],"time":10,"difficulty":"简单","ingredients":[{"name":"荷兰豆","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"口蘑","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["荷兰豆撕去两侧老筋，口蘑切片。","荷兰豆沸水焯 30 秒捞出，生豆含皂素，必须焯熟才安全。","热锅倒油 1 瓷勺，中火爆香蒜片，下口蘑炒 2 分钟至出水变软。","下荷兰豆转大火，加蚝油 1 瓷勺、盐 1 克翻炒 1 分钟，荷兰豆碧绿断生即可。"],"nutrition":{"kcal":105,"protein":6,"fat":6,"carbs":9,"calcium":55,"iron":1.5},"tip":"荷兰豆一定焯熟再炒，生的含皂素易刺激肠胃"},
  {"id":"v40","name":"清炒丝瓜","type":"veg","spicy":false,"tags":["快手","适合老人","时令"],"time":8,"difficulty":"简单","ingredients":[{"name":"丝瓜","amount":300,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["丝瓜去皮切滚刀块，现切现炒不易发黑。","热锅倒油 1 瓷勺，中火爆香蒜片。","下丝瓜转中大火炒 2 分钟，至丝瓜变软微微出汁。","加盐 2 克翻匀立即出锅，丝瓜自带水分，不用加水焖。"],"nutrition":{"kcal":75,"protein":2,"fat":5,"carbs":8,"calcium":30,"iron":0.8},"tip":"丝瓜自带清甜和水分，不用加水焖，软滑口感很适合老人"},
  {"id":"v41","name":"冬瓜虾皮汤","type":"soup","spicy":false,"tags":["补钙","低油","成本超低"],"time":15,"difficulty":"简单","ingredients":[{"name":"冬瓜","amount":300,"unit":"g","category":"蔬菜水果"},{"name":"虾皮","amount":5,"unit":"g","category":"调味干货"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["冬瓜去皮去瓤，切成约 3 毫米的薄片，易熟入味。","锅中加约 500 毫升水烧开，下冬瓜片和虾皮。","中火煮 5 分钟，煮至冬瓜片变透明软塌。","虾皮自带咸味，尝后补盐 1 克即可，撒葱花、点几滴香油出锅。"],"nutrition":{"kcal":55,"protein":4,"fat":3,"carbs":6,"calcium":170,"iron":1},"tip":"冬瓜利水低卡，虾皮提供钙和鲜味，晚餐喝一碗轻负担"},
  {"id":"v42","name":"红烧白萝卜","type":"veg","spicy":false,"tags":["下饭","成本超低","适合老人"],"time":20,"difficulty":"简单","ingredients":[{"name":"白萝卜","amount":350,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"八角","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["白萝卜去皮切滚刀块。","锅中倒油 1 瓷勺，中火把萝卜块煎 3 分钟至边缘微黄，更容易吸味。","加生抽 1 瓷勺、老抽半瓷勺、白糖 1 小勺、八角 1 颗和没过一半萝卜的热水。","加盖中小火焖 12 分钟，至萝卜用筷子能轻松扎透。","开盖转大火收浓汤汁，撒葱花出锅。"],"nutrition":{"kcal":100,"protein":3,"fat":5,"carbs":13,"calcium":60,"iron":0.8},"tip":"萝卜炖软入味像吃肉，价格便宜纤维足，冬季应季更甜"},
  {"id":"v43","name":"蒜蓉蒸金针菇","type":"veg","spicy":false,"tags":["小红书爆款","低油","快手"],"time":15,"difficulty":"简单","ingredients":[{"name":"金针菇","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":25,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["金针菇切去根部，撕成小束铺满盘底。","锅中倒油 1 瓷勺，小火把一半蒜末炒 1 分钟至金黄，关火后拌入另一半生蒜末，金银蒜更香。","蒜蓉均匀铺在金针菇上，水开后上锅大火蒸 8 分钟。","出锅淋蒸鱼豉油 1 瓷勺，撒葱花，再浇 1 瓷勺热油激香即可。"],"nutrition":{"kcal":95,"protein":5,"fat":6,"carbs":9,"calcium":20,"iron":1.2},"tip":"蒸比蒜蓉粉丝版少了精制碳水，金针菇纤维多，饱腹又低卡"},
  {"id":"v44","name":"蚝油双菇","type":"veg","spicy":false,"tags":["下饭","快手"],"time":10,"difficulty":"简单","ingredients":[{"name":"平菇","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蟹味菇","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["平菇手撕成条，蟹味菇切去根部散开，菌菇快速冲净即可，别久泡。","热锅倒油 1 瓷勺，中火爆香蒜末。","下双菇转中大火翻炒 3 分钟，把炒出的水分收干，鲜味才浓。","加蚝油 1 瓷勺、生抽半瓷勺翻匀，收汁后出锅。"],"nutrition":{"kcal":100,"protein":6,"fat":6,"carbs":9,"calcium":15,"iron":1.5},"tip":"菌菇鲜味物质丰富，少盐也够味，是减盐饮食的好帮手"},
  {"id":"v45","name":"清蒸贝贝南瓜","type":"veg","spicy":false,"tags":["儿童友好","低油","适合老人"],"time":20,"difficulty":"简单","ingredients":[{"name":"贝贝南瓜","amount":250,"unit":"g","category":"蔬菜水果"}],"steps":["贝贝南瓜外皮刷洗干净，对半切开，用勺挖净瓜籽和瓜瓤。","切成月牙块，带皮朝下摆入盘中。","蒸锅水开后放入，大火蒸 15 分钟。","用筷子扎一下，能轻松穿透就熟了，粉糯香甜不用任何调味。"],"nutrition":{"kcal":120,"protein":3,"fat":1,"carbs":28,"calcium":40,"iron":1},"tip":"贝贝南瓜粉糯香甜零调味，胡萝卜素丰富，可替代部分主食"},
  {"id":"v46","name":"玉米黄瓜炒三丁","type":"veg","spicy":false,"tags":["儿童友好","快手","爽口"],"time":10,"difficulty":"简单","ingredients":[{"name":"甜玉米","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["甜玉米剥粒，黄瓜、胡萝卜切成和玉米粒差不多大的小丁。","玉米粒和胡萝卜丁沸水焯 1 分钟，断生后更容易炒熟。","热锅倒油 1 瓷勺，大火下三丁翻炒 1 分钟。","加盐 2 克翻匀出锅，颜色鲜亮口感脆甜。"],"nutrition":{"kcal":120,"protein":4,"fat":5,"carbs":18,"calcium":30,"iron":1},"tip":"颜色鲜艳最抓孩子眼球，玉米的叶黄素对眼睛发育友好"},
  {"id":"v47","name":"番茄烧菜花","type":"veg","spicy":false,"tags":["下饭","儿童友好","低油"],"time":15,"difficulty":"简单","ingredients":[{"name":"花菜","amount":250,"unit":"g","category":"蔬菜水果"},{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"番茄酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["花菜掰小朵，沸水焯 2 分钟捞出；番茄切小丁。","热锅倒油 1 瓷勺，中火爆香蒜末，下番茄丁炒 2 分钟至出沙。","加番茄酱 1 瓷勺、白糖 1 小勺、盐 2 克炒匀。","倒入花菜翻匀，加小半碗热水，加盖中火焖 2 分钟。","开盖转大火收浓汤汁，让每朵花菜都裹上酸甜汁。"],"nutrition":{"kcal":110,"protein":5,"fat":5,"carbs":14,"calcium":55,"iron":1.5},"tip":"酸甜浓汁拌饭孩子爱吃，番茄红素经加热更易吸收"},
  {"id":"v48","name":"蒜苔炒木耳","type":"veg","spicy":false,"tags":["深色蔬菜","下饭"],"time":12,"difficulty":"简单","ingredients":[{"name":"蒜苔","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"干木耳","amount":8,"unit":"g","category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["干木耳冷水泡发 2 小时（别超过 4 小时），撕成小朵，沸水焯 1 分钟捞出。","蒜苔洗净切 4 厘米长段。","热锅倒油 1 瓷勺，中大火下蒜苔炒 2 分钟至碧绿断生。","下木耳，加生抽 1 瓷勺、盐 1 克翻炒 1 分钟，木耳噼啪作响就熟了。"],"nutrition":{"kcal":100,"protein":4,"fat":6,"carbs":10,"calcium":60,"iron":3},"tip":"木耳铁含量高又富含可溶纤维，泡发别超过4小时更安全"},
  {"id":"v49","name":"蒜蓉蒸茄子","type":"veg","spicy":false,"tags":["低油","小红书爆款","下饭"],"time":20,"difficulty":"简单","ingredients":[{"name":"茄子","amount":300,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":25,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["茄子洗净切成长条摆入盘中，水开后上锅大火蒸 10 分钟至软。","端出后倒掉盘中蒸出的水，涩味随水一起去掉。","蒜末加生抽半瓷勺、蒸鱼豉油 1 瓷勺、香油几滴调成料汁。","料汁淋在茄子上，撒葱花，吃前拌开即可。"],"nutrition":{"kcal":85,"protein":3,"fat":4,"carbs":12,"calcium":30,"iron":1},"tip":"茄子像海绵吸油，蒸制做法比红烧版能省下大半的油"},
  {"id":"v50","name":"青椒土豆片","type":"veg","spicy":false,"tags":["下饭","成本超低","快手"],"time":12,"difficulty":"简单","ingredients":[{"name":"土豆","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"青椒（菜椒不辣）","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["土豆去皮切薄片，清水冲洗两遍去掉表面淀粉，炒时不粘锅。","青椒去籽切片。","热锅倒油 1 瓷勺，中火爆香蒜片，下土豆片翻炒 3 分钟至边缘半透明。","下青椒转大火，沿锅边淋香醋半瓷勺，加盐 2 克炒匀出锅，醋香让土豆更脆。"],"nutrition":{"kcal":150,"protein":4,"fat":6,"carbs":22,"calcium":25,"iron":1},"tip":"土豆是主食型蔬菜，吃这道菜时米饭减掉小半碗更均衡"},
  {"id":"s09","name":"番茄蛋花汤","type":"soup","spicy":false,"tags":["开胃","快手","成本超低"],"time":8,"difficulty":"简单","ingredients":[{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["番茄顶部划十字，开水烫一下撕去外皮，切小块；鸡蛋打散备用。","热锅倒油 1 小勺，中火把番茄炒 2 分钟至出沙，汤色才浓。","加约 500 毫升热水煮开，转小火，蛋液绕圈缓缓淋入。","等蛋花凝固再轻轻推散，蛋片才大而完整，加盐 2 克调味。","滴几滴香油，撒葱花出锅。"],"nutrition":{"kcal":105,"protein":7,"fat":6,"carbs":6,"calcium":35,"iron":1.2},"tip":"番茄炒出沙后番茄红素更易吸收，餐前喝一碗还能帮助控制食量。"},
  {"id":"s10","name":"紫菜豆腐汤","type":"soup","spicy":false,"tags":["补钙","快手","清爽"],"time":10,"difficulty":"简单","ingredients":[{"name":"干紫菜","amount":3,"unit":"g","category":"调味干货"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"虾皮","amount":3,"unit":"g","category":"调味干货"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["嫩豆腐切小块，紫菜撕小片","水烧开后下豆腐块煮 3 分钟","放入紫菜和虾皮再煮 1 分钟","少盐调味，滴香油撒葱花出锅"],"nutrition":{"kcal":85,"protein":8,"fat":4,"carbs":4,"calcium":180,"iron":2},"tip":"虾皮和紫菜本身带咸鲜味，盐要少放，适合需要控钠又想补钙的家庭。"},
  {"id":"s11","name":"黄瓜蛋花汤","type":"soup","spicy":false,"tags":["清爽","快手","成本超低"],"time":8,"difficulty":"简单","ingredients":[{"name":"黄瓜","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"虾皮","amount":2,"unit":"g","category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["黄瓜洗净切成薄片，鸡蛋磕入碗中充分打散备用","锅中加约 2 碗清水烧开，下黄瓜片和虾皮，中火煮 1 分钟至黄瓜微微变透","保持汤微沸，将蛋液绕圈缓缓淋入，停 5 秒再轻轻推动，蛋花更大更嫩，随即关火","加盐约 1 克调味，滴几滴香油即可盛出，虾皮本身带咸鲜，盐不用多"],"nutrition":{"kcal":80,"protein":7,"fat":5,"carbs":3,"calcium":60,"iron":1},"tip":"黄瓜下锅时间短口感更脆嫩，夏天喝清爽补水，热量很低。"},
  {"id":"s13","name":"金针菇肉丝汤","type":"soup","spicy":false,"tags":["开胃","快手"],"time":10,"difficulty":"简单","ingredients":[{"name":"金针菇","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"猪里脊肉","amount":40,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["里脊逆纹切细丝，加料酒半瓷勺和淀粉 1 小勺抓匀，腌 5 分钟上浆","金针菇切去根部撕散，冲洗干净；姜切细丝，小葱切葱花","锅中加约 2 碗清水烧开，下姜丝和金针菇，中火煮 2 分钟","转小火下肉丝快速滑散，煮 1 分钟至完全变色","加盐约 2 克调味，撒葱花出锅"],"nutrition":{"kcal":90,"protein":10,"fat":3,"carbs":6,"calcium":15,"iron":1.2},"tip":"肉丝上浆后再下锅口感嫩滑，金针菇富含膳食纤维，饭前喝助增饱腹感。"},
  {"id":"s14","name":"西葫芦虾仁汤","type":"soup","spicy":false,"tags":["清爽","快手","儿童友好"],"time":10,"difficulty":"简单","ingredients":[{"name":"西葫芦","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"冷冻虾仁","amount":60,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["虾仁提前解冻，用厨房纸吸干水分，加料酒半瓷勺腌 5 分钟去腥","西葫芦洗净对半剖开，切成半圆薄片；姜切细丝","锅中加约 2 碗清水烧开，下姜丝和西葫芦片，中火煮 2 分钟至半透明","下虾仁煮约 1 分钟，看到虾仁变红卷起就熟了","加盐约 2 克调味，滴几滴香油即可出锅"],"nutrition":{"kcal":75,"protein":12,"fat":2,"carbs":4,"calcium":50,"iron":0.9},"tip":"虾仁高蛋白低脂肪，汤色清甜不腥，是孩子容易接受的补蛋白快手汤。"},
  {"id":"s15","name":"平菇肉片汤","type":"soup","spicy":false,"tags":["快手","适合老人"],"time":12,"difficulty":"简单","ingredients":[{"name":"平菇","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"猪里脊肉","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["平菇撕成小条洗净；里脊逆纹切薄片，加淀粉 1 小勺和少许清水抓匀上浆","锅中加约 2 碗清水烧开，下姜丝和平菇，中火煮 3 分钟煮出鲜味","转小火，肉片逐片下锅滑散，煮 1 分钟至完全变色","加盐约 2 克和少许黑胡椒调味，撒葱花出锅"],"nutrition":{"kcal":95,"protein":11,"fat":3,"carbs":7,"calcium":12,"iron":1.4},"tip":"菌菇的鲜味物质能替代部分盐，汤鲜味足，适合牙口一般的老人。"},
  {"id":"s16","name":"青菜豆腐汤","type":"soup","spicy":false,"tags":["清爽","成本超低","适合老人"],"time":10,"difficulty":"简单","ingredients":[{"name":"上海青","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"虾皮","amount":2,"unit":"g","category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["上海青洗净切段，嫩豆腐切成约 2 厘米见方的小块","锅中加约 2 碗清水烧开，滴几滴食用油让汤更润，轻轻推入豆腐煮 3 分钟","放入上海青和虾皮再煮 1 分钟，青菜变翠绿即可","加盐约 1 克调味出锅，虾皮本身带咸鲜，盐不用多"],"nutrition":{"kcal":75,"protein":8,"fat":3,"carbs":4,"calcium":190,"iron":1.8},"tip":"青菜加豆腐是经典补钙组合，绿叶菜煮的时间短，维生素 C 保留更多。"},
  {"id":"s17","name":"酸辣汤","type":"soup","spicy":true,"tags":["开胃","快手"],"time":15,"difficulty":"中等","ingredients":[{"name":"嫩豆腐","amount":100,"unit":"g","category":"奶品豆制品"},{"name":"金针菇","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"干木耳","amount":5,"unit":"g","category":"调味干货"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"香醋","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["干木耳提前温水泡发 20 分钟切细丝；豆腐、胡萝卜切细丝，金针菇撕散切段","锅中加约 2 碗清水烧开，下木耳丝、胡萝卜丝和金针菇煮 2 分钟，再轻轻放入豆腐丝煮 1 分钟","加生抽 1 瓷勺、盐 1 克，淀粉加水调开淋入勾薄芡，煮至汤微微浓稠","保持小火，绕圈淋入蛋液，稍等几秒再轻推成蛋花","关火后加香醋 1 瓷勺和现磨黑胡椒，酸辣味出锅前放才够冲"],"nutrition":{"kcal":110,"protein":9,"fat":5,"carbs":9,"calcium":130,"iron":2.5},"tip":"酸味来自醋、辣味来自胡椒，不额外加辣油，开胃又不给肠胃增加负担。"},
  {"id":"s18","name":"番茄疙瘩汤","type":"soup","spicy":false,"tags":["开胃","儿童友好","快手"],"time":15,"difficulty":"中等","ingredients":[{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"面粉","amount":30,"unit":"g","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["面粉放入大碗，边滴入少量清水边用筷子快速搅动，搅成绿豆大小的小疙瘩","番茄切小块；热锅倒少许油，中火把番茄炒 2 分钟至出沙","加约 2 碗清水煮开，转中小火，分次拨入面疙瘩，边下边搅防止粘连","煮 3 分钟至疙瘩浮起无白芯，绕圈淋入蛋液成蛋花","加盐约 2 克，滴几滴香油撒葱花出锅"],"nutrition":{"kcal":140,"protein":8,"fat":5,"carbs":17,"calcium":30,"iron":1.3},"tip":"经典北方家常汤，带主食属性，胃口不好或感冒时喝一碗暖胃又易消化。"},
  {"id":"s19","name":"甜玉米蛋花羹","type":"soup","spicy":false,"tags":["儿童友好","快手","开胃"],"time":10,"difficulty":"简单","ingredients":[{"name":"甜玉米","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"白糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["甜玉米剥粒洗净，鸡蛋打散备用","锅中加约 2 碗清水，下玉米粒大火煮开转中火煮 5 分钟至熟","淀粉 1 瓷勺加 2 瓷勺清水调开，淋入锅中搅匀，煮至汤汁微微浓稠","转小火，绕圈淋入蛋液，稍等几秒再轻轻划出蛋花","加盐约 1 克和一小撮白糖提味即可"],"nutrition":{"kcal":130,"protein":8,"fat":5,"carbs":15,"calcium":30,"iron":1},"tip":"玉米自带清甜，糖只需一点点提味，是孩子接受度极高的一道羹汤。"},
  {"id":"s20","name":"虾仁豆腐羹","type":"soup","spicy":false,"tags":["补钙","儿童友好"],"time":15,"difficulty":"中等","ingredients":[{"name":"冷冻虾仁","amount":60,"unit":"g","category":"水产海鲜"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["虾仁解冻后吸干水分切小丁，加料酒半瓷勺腌 5 分钟去腥","嫩豆腐切小丁；锅中加约 2 碗清水烧开，轻轻下豆腐煮 2 分钟","下虾仁丁煮 1 分钟至变红，淀粉加水调开淋入勾薄芡","转小火绕圈淋入蛋液，轻推成蛋花，加盐约 2 克","滴几滴香油，撒葱花即可出锅"],"nutrition":{"kcal":135,"protein":16,"fat":6,"carbs":6,"calcium":160,"iron":1.6},"tip":"虾仁加豆腐蛋白质互补，质地软嫩，特别适合幼儿和咀嚼不便的老人。"},
  {"id":"s21","name":"粉丝丸子汤","type":"soup","spicy":false,"tags":["儿童友好","开胃"],"time":20,"difficulty":"中等","ingredients":[{"name":"猪肉末","amount":70,"unit":"g","category":"肉禽蛋"},{"name":"龙口粉丝","amount":20,"unit":"g","category":"米面粮油"},{"name":"上海青","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["肉末加姜末、料酒半瓷勺、生抽 1 瓷勺、淀粉 1 小勺，顺一个方向搅 2 分钟至上劲","粉丝温水泡 10 分钟至软，剪成短段；上海青洗净切段","锅中加约 2 碗清水烧至锅底冒小泡（八成开），用虎口挤出丸子逐个下锅","中小火煮至丸子全部浮起，再煮 2 分钟确保熟透","下粉丝和上海青煮 2 分钟，加盐约 1 克，撒葱花出锅"],"nutrition":{"kcal":140,"protein":13,"fat":6,"carbs":10,"calcium":45,"iron":1.5},"tip":"丸子在水将开未开时下锅不易散，自制丸子比市售的钠和脂肪都更可控。"},
  {"id":"s22","name":"奶香玉米浓汤","type":"soup","spicy":false,"tags":["儿童友好","补钙"],"time":20,"difficulty":"中等","ingredients":[{"name":"甜玉米","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"土豆","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"纯牛奶","amount":150,"unit":"ml","category":"奶品豆制品"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["甜玉米剥粒，土豆去皮切小块","锅中加约 1 碗清水，下玉米和土豆中火煮 10 分钟，至土豆一压即碎","稍晾 2 分钟，连汤倒入料理机打成细腻糊状，小心烫","倒回锅中加入牛奶搅匀，小火煮至微微冒泡即离火，不要大滚以免奶味发散","加盐约 1 克和少许黑胡椒调味即可"],"nutrition":{"kcal":140,"protein":6,"fat":5,"carbs":20,"calcium":160,"iron":0.6},"tip":"用牛奶和土豆打底代替奶油和黄油，同样浓郁顺滑，脂肪却少一大半。"},
  {"id":"s23","name":"莲藕排骨汤","type":"soup","spicy":false,"tags":["周末煲汤","滋补","适合老人"],"time":90,"difficulty":"中等","ingredients":[{"name":"猪肋排","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"莲藕","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["排骨冷水下锅，加料酒 1 瓷勺，大火煮开撇净浮沫，捞出用温水冲洗干净","莲藕去皮切滚刀块，炖汤选粉藕口感更绵糯","排骨放入汤锅，加姜片和约 4 碗热水，大火烧开转小火加盖炖 1 小时","下藕块继续小火炖 30 分钟，至筷子能轻松扎透排骨和藕","出锅前加盐约 2 克调味，撒葱花即可"],"nutrition":{"kcal":140,"protein":11,"fat":8,"carbs":12,"calcium":40,"iron":1.6},"tip":"粉藕久炖更绵糯，盐最后放可减少用量；喝汤记得把肉和藕一起吃掉。"},
  {"id":"s24","name":"海带筒骨汤","type":"soup","spicy":false,"tags":["周末煲汤","补钙","滋补"],"time":120,"difficulty":"中等","ingredients":[{"name":"猪筒骨","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"海带","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香醋","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["筒骨冷水下锅，加料酒 1 瓷勺焯水，煮开撇净浮沫后捞出冲净","海带洗去表面粘液，切成一口大小的块","筒骨放入汤锅，加姜片、几滴香醋和约 4 碗热水，大火烧开转小火加盖炖 1.5 小时","下海带再炖 30 分钟至软糯","加盐约 2 克调味即可，喝前撇去表面浮油更清爽"],"nutrition":{"kcal":110,"protein":8,"fat":6,"carbs":5,"calcium":90,"iron":1.2},"tip":"炖骨汤加几滴醋有助矿物质溶出；海带补碘，甲状腺疾病患者需遵医嘱。"},
  {"id":"s25","name":"香菇炖鸡汤","type":"soup","spicy":false,"tags":["周末煲汤","滋补"],"time":60,"difficulty":"中等","ingredients":[{"name":"鸡腿肉","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"干香菇","amount":8,"unit":"g","category":"调味干货"},{"name":"红枣","amount":10,"unit":"g","category":"调味干货"},{"name":"枸杞","amount":3,"unit":"g","category":"调味干货"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["干香菇温水泡发 30 分钟，泡菇水静置沉淀后留用；红枣冲洗备用","鸡腿肉切块冷水下锅，加料酒 1 瓷勺焯水，煮开撇沫后捞出冲净","鸡块、香菇、红枣放入汤锅，加姜片，倒入泡菇水并补热水至约 3 碗，大火烧开转小火炖 50 分钟","出锅前 5 分钟放入枸杞","加盐约 2 克调味即可，香菇够鲜，盐可酌情再减"],"nutrition":{"kcal":135,"protein":14,"fat":6,"carbs":8,"calcium":20,"iron":1.5},"tip":"泡香菇的水别倒掉，鲜味核苷酸都在里面，能让鸡汤更鲜而少放盐。"},
  {"id":"s26","name":"白萝卜牛腩汤","type":"soup","spicy":false,"tags":["周末煲汤","适合老人","滋补"],"time":100,"difficulty":"中等","ingredients":[{"name":"牛腩","amount":70,"unit":"g","category":"肉禽蛋"},{"name":"白萝卜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"八角","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["牛腩切块冷水下锅，加料酒 1 瓷勺焯水，煮开撇净浮沫后捞出洗净","牛腩放入汤锅，加姜片、1 颗八角和约 4 碗热水，大火烧开转小火加盖炖 70 分钟","白萝卜去皮切滚刀块下锅，再炖 25 分钟至萝卜透明软烂","加盐约 2 克调味，撒葱花出锅"],"nutrition":{"kcal":125,"protein":12,"fat":6,"carbs":6,"calcium":35,"iron":2.2},"tip":"牛腩富含铁和优质蛋白，萝卜炖到透亮入口即化，很适合老人补铁。"},
  {"id":"s28","name":"冰糖绿豆汤","type":"soup","spicy":false,"tags":["清润","成本超低","周末煲汤"],"time":45,"difficulty":"简单","ingredients":[{"name":"绿豆","amount":30,"unit":"g","category":"米面粮油"},{"name":"冰糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["绿豆淘洗后清水浸泡 30 分钟","加约 6 倍水，大火煮开转小火","煮 30 分钟至绿豆开花","加少量冰糖搅化，放温饮用"],"nutrition":{"kcal":105,"protein":6,"fat":0.3,"carbs":20,"calcium":25,"iron":1.8},"tip":"夏日消暑经典，糖越少越好；连豆一起吃能获得更多蛋白质和膳食纤维。"},
  {"id":"s29","name":"银耳红枣汤","type":"soup","spicy":false,"tags":["清润","滋补","适合老人"],"time":60,"difficulty":"简单","ingredients":[{"name":"银耳","amount":10,"unit":"g","category":"调味干货"},{"name":"红枣","amount":15,"unit":"g","category":"调味干货"},{"name":"枸杞","amount":3,"unit":"g","category":"调味干货"},{"name":"冰糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["银耳提前泡发 1 小时，撕小朵去黄根","银耳加足量水，大火煮开转小火炖 40 分钟","加红枣继续炖 15 分钟至出胶","放枸杞和少量冰糖，再煮 5 分钟"],"nutrition":{"kcal":90,"protein":2,"fat":0.3,"carbs":21,"calcium":30,"iron":1},"tip":"银耳的顺滑来自可溶性膳食纤维，对肠道友好；控糖人群可不加冰糖。"},
  {"id":"s30","name":"冬瓜薏米汤","type":"soup","spicy":false,"tags":["清润","清爽","周末煲汤"],"time":60,"difficulty":"简单","ingredients":[{"name":"冬瓜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"薏米","amount":20,"unit":"g","category":"米面粮油"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["薏米淘洗后清水浸泡 1 小时，更容易煮软","薏米放入汤锅，加姜片和约 3 碗清水，大火煮开转小火煮 40 分钟至薏米开花","冬瓜连皮洗净切块下锅，再煮 15 分钟至冬瓜呈半透明","加盐约 1 克调味即可"],"nutrition":{"kcal":85,"protein":3,"fat":0.5,"carbs":18,"calcium":30,"iron":1},"tip":"冬瓜连皮煮汤钾和膳食纤维更足，这碗汤低脂低钠，湿热天气很合适。"},
  {"id":"st04","name":"小米红枣粥","type":"staple","spicy":false,"tags":["粗粮","儿童友好","一锅出"],"time":35,"difficulty":"简单","ingredients":[{"name":"小米","amount":55,"unit":"g","category":"米面粮油"},{"name":"红枣","amount":12,"unit":"g","category":"调味干货"}],"steps":["小米淘洗一遍，红枣去核切小块","加约 8 倍水，大火煮开","转小火熬 25 分钟，中途搅动防粘底","熬至粥面浮起米油即可"],"nutrition":{"kcal":240,"protein":6,"fat":2,"carbs":50,"calcium":25,"iron":3},"tip":"小米富含 B 族维生素，红枣自带甜味无需加糖，适合当早餐或晚餐主食。"},
  {"id":"st05","name":"黑米饭","type":"staple","spicy":false,"tags":["粗粮","控糖","主食"],"time":45,"difficulty":"简单","ingredients":[{"name":"大米","amount":50,"unit":"g","category":"米面粮油"},{"name":"黑米","amount":25,"unit":"g","category":"米面粮油"}],"steps":["黑米提前浸泡 2 小时，泡米水别倒","与淘净的大米混合放入电饭煲","水量比纯白米饭略多一点","按煮饭键，跳闸后焖 10 分钟"],"nutrition":{"kcal":260,"protein":6,"fat":1,"carbs":56,"calcium":15,"iron":1.8},"tip":"黑米的花青素在泡米水里，连水一起煮不浪费；粗细搭配升糖更平稳。"},
  {"id":"st06","name":"藜麦糙米饭","type":"staple","spicy":false,"tags":["控糖","粗粮","饱腹"],"time":50,"difficulty":"简单","ingredients":[{"name":"大米","amount":40,"unit":"g","category":"米面粮油"},{"name":"糙米","amount":20,"unit":"g","category":"米面粮油"},{"name":"藜麦","amount":15,"unit":"g","category":"米面粮油"}],"steps":["糙米提前浸泡 1 小时","藜麦用细网筛冲洗去皂苷","三种米混合，水量为米的 1.3 倍","电饭煲煮熟后焖 10 分钟再开盖"],"nutrition":{"kcal":265,"protein":7,"fat":2,"carbs":54,"calcium":20,"iron":1.6},"tip":"藜麦是优质植物蛋白来源，配糙米升糖指数低，适合控糖和减脂人群。"},
  {"id":"st07","name":"燕麦米饭","type":"staple","spicy":false,"tags":["控糖","粗粮","饱腹"],"time":50,"difficulty":"简单","ingredients":[{"name":"大米","amount":50,"unit":"g","category":"米面粮油"},{"name":"燕麦米","amount":25,"unit":"g","category":"米面粮油"}],"steps":["燕麦米提前浸泡 1 小时","与淘净的大米混合入锅","水量比平时煮白米饭多一成","煮熟后焖 10 分钟，口感更弹润"],"nutrition":{"kcal":260,"protein":7,"fat":2,"carbs":53,"calcium":18,"iron":1.5},"tip":"燕麦米的 β-葡聚糖有助平稳餐后血糖、辅助降胆固醇，嚼劲足更耐饿。"},
  {"id":"st08","name":"绿豆饭","type":"staple","spicy":false,"tags":["粗粮","主食","饱腹"],"time":50,"difficulty":"简单","ingredients":[{"name":"大米","amount":55,"unit":"g","category":"米面粮油"},{"name":"绿豆","amount":20,"unit":"g","category":"米面粮油"}],"steps":["绿豆提前浸泡 2 小时","与淘净的大米混合放入电饭煲","水量比纯白米饭略多","煮熟焖 10 分钟后拌匀盛出"],"nutrition":{"kcal":255,"protein":8,"fat":1,"carbs":54,"calcium":25,"iron":2},"tip":"豆类和大米蛋白质互补，整体蛋白质利用率更高，夏天吃还清爽解腻。"},
  {"id":"st09","name":"荞麦汤面","type":"staple","spicy":false,"tags":["控糖","快手","主食"],"time":12,"difficulty":"简单","ingredients":[{"name":"荞麦面","amount":75,"unit":"g","category":"米面粮油"},{"name":"上海青","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["水开后下荞麦面，按包装时间煮熟","最后 1 分钟放入上海青烫熟","碗中放生抽、香油和少许盐，冲入面汤","捞入面条和青菜，撒葱花即可"],"nutrition":{"kcal":270,"protein":10,"fat":3,"carbs":53,"calcium":60,"iron":2.5},"tip":"荞麦面升糖指数低于白面条，饱腹感强，控糖人群可放心作为主食轮换。"},
  {"id":"st10","name":"全麦馒头","type":"staple","spicy":false,"tags":["粗粮","快手","主食"],"time":10,"difficulty":"简单","ingredients":[{"name":"全麦馒头","amount":1,"unit":"个","category":"米面粮油"}],"steps":["蒸锅加水烧开","馒头放入蒸屉，中火蒸 8 分钟","关火焖 1 分钟取出，趁热食用"],"nutrition":{"kcal":235,"protein":8,"fat":1.5,"carbs":48,"calcium":30,"iron":2.2},"tip":"选配料表以全麦粉排第一位的馒头，膳食纤维更足，冷冻保存随蒸随吃。"},
  {"id":"st11","name":"葱香花卷","type":"staple","spicy":false,"tags":["快手","儿童友好","主食"],"time":10,"difficulty":"简单","ingredients":[{"name":"花卷","amount":1,"unit":"个","category":"米面粮油"}],"steps":["蒸锅加水烧开","花卷放入蒸屉，中火蒸 8 分钟","关火焖 1 分钟，松软即食"],"nutrition":{"kcal":250,"protein":7,"fat":4,"carbs":46,"calcium":25,"iron":1.8},"tip":"花卷含油盐略高于馒头，当天搭配的菜可以做得清淡些来平衡钠摄入。"},
  {"id":"st12","name":"牛奶燕麦粥","type":"staple","spicy":false,"tags":["快手","儿童友好","控糖"],"time":8,"difficulty":"简单","ingredients":[{"name":"即食燕麦片","amount":40,"unit":"g","category":"米面粮油"},{"name":"纯牛奶","amount":200,"unit":"ml","category":"奶品豆制品"}],"steps":["小锅加半碗水烧开，倒入燕麦片","小火煮 2 分钟至浓稠","倒入牛奶搅匀，煮至微微冒泡关火","静置 1 分钟口感更顺滑"],"nutrition":{"kcal":275,"protein":12,"fat":9,"carbs":38,"calcium":240,"iron":1.8},"tip":"一碗同时补钙和膳食纤维，选纯燕麦片而非风味麦片，可避免添加糖。"},
  {"id":"st13","name":"玉米糁粥","type":"staple","spicy":false,"tags":["粗粮","一锅出","主食"],"time":30,"difficulty":"简单","ingredients":[{"name":"玉米糁","amount":60,"unit":"g","category":"米面粮油"}],"steps":["玉米糁用少量凉水调开防结块","锅中水烧开，边搅边倒入玉米糁","小火熬 20 分钟，勤搅拌防粘底","熬至浓稠冒泡即可"],"nutrition":{"kcal":230,"protein":5,"fat":2,"carbs":49,"calcium":10,"iron":1.5},"tip":"北方家常棒子面粥，玉米黄素对眼睛友好，配个鸡蛋和青菜就是一餐。"},
  {"id":"st14","name":"二米饭","type":"staple","spicy":false,"tags":["粗粮","儿童友好","主食"],"time":40,"difficulty":"简单","ingredients":[{"name":"大米","amount":50,"unit":"g","category":"米面粮油"},{"name":"小米","amount":25,"unit":"g","category":"米面粮油"}],"steps":["大米和小米一起淘洗两遍","放入电饭煲，水量与白米饭相同","按煮饭键，跳闸后焖 10 分钟","拌松散热气即可盛出"],"nutrition":{"kcal":265,"protein":6,"fat":1.5,"carbs":57,"calcium":15,"iron":1.6},"tip":"小米无需浸泡就能与大米同煮，是全家最容易接受的粗粮入门吃法。"},
  {"id":"st15","name":"阳春面","type":"staple","spicy":false,"tags":["快手","主食","饱腹"],"time":10,"difficulty":"简单","ingredients":[{"name":"挂面","amount":75,"unit":"g","category":"米面粮油"},{"name":"小葱","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["碗中放生抽、少许盐、香油和葱花","水开后下挂面煮 3 分钟至无硬芯","舀一勺滚烫面汤冲开碗底料","捞入面条拌匀即可"],"nutrition":{"kcal":270,"protein":8,"fat":3,"carbs":54,"calcium":15,"iron":1.4},"tip":"挂面本身含钠，碗底盐要少放；加个荷包蛋和青菜营养会更完整。"},
  {"id":"m77","name":"冬瓜烧虾仁","type":"meat","spicy":false,"tags":["低脂","高蛋白","适合老人"],"time":15,"difficulty":"简单","ingredients":[{"name":"冷冻虾仁","amount":70,"unit":"g","category":"水产海鲜"},{"name":"冬瓜","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["虾仁解冻擦干，用盐和淀粉抓匀腌 5 分钟；冬瓜去皮切厚片。","热锅少油下姜丝，冬瓜片煎至两面微透明。","加小半碗热水焖 3 分钟至冬瓜软糯。","下虾仁烧 2 分钟至变色，淀粉水勾薄芡，撒葱花出锅。"],"nutrition":{"kcal":120,"protein":15,"fat":4,"carbs":6,"calcium":60,"iron":1.2},"tip":"虾仁高蛋白低脂肪，冬瓜清爽多汁，这道菜热量低又顶饱，适合控体重的成员。"},
  {"id":"s32","name":"娃娃菜粉丝汤","type":"soup","spicy":false,"tags":["清爽","快手","成本超低"],"time":12,"difficulty":"简单","ingredients":[{"name":"娃娃菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"龙口粉丝","amount":15,"unit":"g","category":"米面粮油"},{"name":"虾皮","amount":2,"unit":"g","category":"调味干货"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["粉丝温水泡软；娃娃菜纵切成条。","少油爆香蒜片和虾皮，下娃娃菜炒软。","加两碗热水烧开，下粉丝煮 2 分钟。","加盐调味，滴香油出锅。"],"nutrition":{"kcal":80,"protein":3,"fat":3,"carbs":12,"calcium":70,"iron":0.8},"tip":"娃娃菜甜嫩易消化，粉丝吸味，一碗汤兼顾了蔬菜和一点主食。"},
  {"id":"m78","name":"黄焖鸡","type":"meat","spicy":false,"tags":["下饭","家常","砂锅"],"time":35,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"土豆","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"干香菇","amount":8,"unit":"g","category":"调味干货"},{"name":"青椒（菜椒不辣）","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"老抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"白糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["干香菇提前温水泡发 30 分钟，泡香菇的水留用；鸡腿肉切块，土豆切滚刀块，青椒切片。","热锅倒油，下姜片和鸡块中火煸炒至表面微黄，淋料酒半瓷勺去腥。","加生抽 1 瓷勺、老抽半瓷勺、白糖 1 小勺翻炒上色，放入香菇和土豆，倒入泡香菇水没过食材。","盖盖小火焖 20 分钟至土豆软糯，开盖转大火收浓汤汁，放青椒片翻炒 1 分钟即可。"],"nutrition":{"kcal":310,"protein":24,"fat":18,"carbs":16,"calcium":30,"iron":1.6},"tip":"泡香菇的水是天然提鲜剂，别倒掉；用砂锅焖香味更浓。","heavy":true},
  {"id":"m79","name":"芹菜炒牛肉丝","type":"meat","spicy":false,"tags":["快手","高蛋白","下饭"],"time":15,"difficulty":"简单","ingredients":[{"name":"牛里脊","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"芹菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"蚝油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["牛里脊逆纹切丝，加生抽 1 瓷勺、玉米淀粉 1 小勺和少许食用油抓匀，腌 10 分钟。","芹菜撕去老筋切段，放入开水快焯 20 秒捞出沥干，保持脆嫩。","热锅热油，下牛肉丝大火滑炒约 1 分钟至变色，立即盛出。","锅内余油爆香姜蒜，下芹菜翻炒 1 分钟，倒回牛肉丝，加蚝油 1 瓷勺和盐 1 克，大火炒匀出锅。"],"nutrition":{"kcal":220,"protein":22,"fat":11,"carbs":7,"calcium":55,"iron":3},"tip":"牛肉一定要逆着纹路切，滑炒时间不超过 1 分钟才嫩。"},
  {"id":"m80","name":"番茄炖牛腩","type":"meat","spicy":false,"tags":["炖菜","开胃","汤汁拌饭"],"time":90,"difficulty":"中等","ingredients":[{"name":"牛腩","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"八角","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"番茄酱","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["牛腩切块冷水下锅，加姜片、料酒 1 瓷勺焯水，煮开撇净浮沫后捞出洗净。","番茄顶部划十字，开水烫 1 分钟撕去外皮，一半切块一半切碎。","热锅少油，下碎番茄和番茄酱 1 瓷勺中火炒出红油，下牛腩、姜片、八角翻炒，加热水没过食材。","小火加盖炖 1 小时，放入番茄块、生抽 1 瓷勺和盐约 2 克，再炖 15 分钟至汤浓肉烂，撒葱花出锅。"],"nutrition":{"kcal":320,"protein":23,"fat":22,"carbs":9,"calcium":25,"iron":3.2},"tip":"番茄分两次放：先炒碎的出味，后放块的保口感；用高压锅可缩短到 30 分钟。","heavy":true},
  {"id":"m81","name":"孜然羊肉","type":"meat","spicy":true,"tags":["下饭","高蛋白","冬季暖身"],"time":15,"difficulty":"简单","ingredients":[{"name":"羊肉片","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"孜然粉","amount":3,"unit":"g","category":"调味干货"},{"name":"小葱","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"干辣椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["羊肉片加生抽 1 瓷勺、料酒半瓷勺、玉米淀粉 1 小勺抓匀，腌 10 分钟。","热锅多放一点油烧至微微冒烟，大火下羊肉片快速滑散，炒约 1 分钟至变色。","下干辣椒段炒香，撒孜然粉和盐约 1 克，快速翻炒均匀。","出锅前撒葱段，翻两下立刻装盘，久炒羊肉会老。"],"nutrition":{"kcal":280,"protein":23,"fat":19,"carbs":4,"calcium":20,"iron":2.8},"tip":"全程大火快炒，羊肉片下锅后不要超过 2 分钟，久了会老。","heavy":true},
  {"id":"m82","name":"肥牛娃娃菜粉丝煲","type":"meat","spicy":false,"tags":["一锅出","砂锅","汤鲜"],"time":25,"difficulty":"简单","ingredients":[{"name":"肥牛卷","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"娃娃菜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"龙口粉丝","amount":30,"unit":"g","category":"米面粮油"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蚝油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["粉丝温水泡 10 分钟至软；娃娃菜切长条铺在砂锅底，泡软的粉丝铺在菜上。","热油爆香蒜末，加生抽 1 瓷勺、蚝油 1 瓷勺和半碗热水调成汤汁，浇入砂锅。","盖盖中火煮 8 分钟，至娃娃菜软塌出汁。","铺上肥牛卷再盖盖煮 2 分钟至完全变色，尝味后酌情补盐，撒葱花即可。"],"nutrition":{"kcal":330,"protein":18,"fat":20,"carbs":24,"calcium":60,"iron":2},"tip":"粉丝会吸汤，汤汁可比平时多放一点；肥牛最后放才嫩。","heavy":true},
  {"id":"m83","name":"蒜香煎鸡翅","type":"meat","spicy":false,"tags":["孩子爱吃","少油版","快手"],"time":25,"difficulty":"简单","ingredients":[{"name":"鸡翅中","amount":180,"unit":"g","category":"肉禽蛋"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"蚝油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鸡翅两面各划两刀方便入味，加蒜末、生抽 1 瓷勺、蚝油 1 瓷勺、料酒半瓷勺和黑胡椒抓匀，腌 20 分钟以上。","平底锅刷薄油，小火放入鸡翅，每面煎 4～5 分钟至金黄。","倒入剩余腌料汁和 2 瓷勺清水，盖盖小火焖 5 分钟确保熟透。","开盖转大火收汁，让每只鸡翅均匀裹上酱汁即可。"],"nutrition":{"kcal":290,"protein":22,"fat":20,"carbs":5,"calcium":15,"iron":1.2},"tip":"腌制时间越长越入味，可以头天晚上腌好放冷藏，第二天煎更省事。","heavy":true},
  {"id":"m84","name":"白萝卜炖鸭腿","type":"meat","spicy":false,"tags":["炖汤","秋冬润燥","老少皆宜"],"time":70,"difficulty":"简单","ingredients":[{"name":"鸭腿","amount":200,"unit":"g","category":"肉禽蛋"},{"name":"白萝卜","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"枸杞","amount":3,"unit":"g","category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鸭腿剁块冷水下锅，加姜片、料酒 1 瓷勺焯水，煮开撇沫后捞出冲净。","鸭块放入汤锅，加姜片和约 4 碗热水，大火烧开转小火加盖炖 40 分钟。","白萝卜去皮切块放入，继续炖 20 分钟至萝卜透明软烂。","加盐约 2 克调味，撒枸杞焖 2 分钟，出锅点缀葱花。"],"nutrition":{"kcal":300,"protein":24,"fat":21,"carbs":7,"calcium":40,"iron":2.5},"tip":"鸭肉偏油，炖好后可撇去表面浮油再喝汤，更清爽。","heavy":true},
  {"id":"m85","name":"香煎鳕鱼","type":"meat","spicy":false,"tags":["高蛋白","低脂","宝宝也能吃"],"time":15,"difficulty":"简单","ingredients":[{"name":"鳕鱼","amount":150,"unit":"g","category":"水产海鲜"},{"name":"柠檬","amount":0.5,"unit":"个","category":"蔬菜水果"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鳕鱼解冻后用厨房纸彻底吸干水分，两面抹盐约 1 克和黑胡椒，腌 10 分钟。","表面薄薄拍一层玉米淀粉，防粘且锁住水分。","平底锅热油，中小火放入鳕鱼，先煎约 3 分钟至底面定型金黄再翻面，另一面同样煎约 3 分钟。","出锅装盘，挤上柠檬汁趁热食用。"],"nutrition":{"kcal":200,"protein":26,"fat":8,"carbs":5,"calcium":30,"iron":0.8},"tip":"鳕鱼肉嫩易碎，煎时不要频繁翻动，等底面定型再翻。","heavy":true},
  {"id":"m86","name":"青椒炒鱿鱼","type":"meat","spicy":false,"tags":["快手","低脂","下饭"],"time":15,"difficulty":"中等","ingredients":[{"name":"鱿鱼","amount":150,"unit":"g","category":"水产海鲜"},{"name":"青椒（菜椒不辣）","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"蚝油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鱿鱼撕去外膜洗净，内侧打十字花刀后切块。","水烧开加料酒 1 瓷勺和姜片，鱿鱼下锅焯 10 秒，打卷立刻捞出沥干。","热锅热油爆香姜蒜，下青椒块大火炒 1 分钟至断生。","倒入鱿鱼，加生抽 1 瓷勺、蚝油半瓷勺，大火翻炒 30 秒立即出锅。"],"nutrition":{"kcal":185,"protein":23,"fat":7,"carbs":7,"calcium":45,"iron":1},"tip":"鱿鱼焯水看到打卷就捞，全程动作要快，炒老了嚼不动。"},
  {"id":"m87","name":"丝瓜蛤蜊豆腐汤","type":"soup","spicy":false,"tags":["清淡","夏季","补钙"],"time":20,"difficulty":"简单","ingredients":[{"name":"蛤蜊","amount":300,"unit":"g","category":"水产海鲜"},{"name":"丝瓜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"嫩豆腐","amount":150,"unit":"g","category":"奶品豆制品"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["蛤蜊提前用淡盐水浸泡 2 小时吐净泥沙，冲洗干净；丝瓜去皮切滚刀块，嫩豆腐切块。","热锅少油煸香姜片，下丝瓜略炒出香，加约 2 碗热水烧开。","放入豆腐煮 3 分钟，再下蛤蜊煮约 2 分钟至全部开口。","加盐约 1 克调味，滴几滴香油撒葱花即可，蛤蜊本身带咸鲜，盐要少放。"],"nutrition":{"kcal":185,"protein":17,"fat":8,"carbs":10,"calcium":180,"iron":6},"tip":"蛤蜊本身很鲜且带咸味，盐要最后尝过再加；开口即熟，久煮变硬。"},
  {"id":"m88","name":"韭菜炒虾仁","type":"meat","spicy":false,"tags":["快手","高蛋白","低脂"],"time":10,"difficulty":"简单","ingredients":[{"name":"冷冻虾仁","amount":150,"unit":"g","category":"水产海鲜"},{"name":"韭菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["冷冻虾仁提前解冻，用厨房纸吸干水分，加料酒半瓷勺、盐 1 克和玉米淀粉半瓷勺抓匀，腌 5 分钟。","韭菜洗净切 4 厘米长段，梗和叶分开放；姜切末。","热锅倒油 1 瓷勺，油热下姜末和虾仁，大火炒约 1 分钟至虾仁变红弯曲。","先下韭菜梗炒 30 秒，再下韭菜叶，加盐 1 克快速翻匀立即出锅。"],"nutrition":{"kcal":200,"protein":24,"fat":9,"carbs":6,"calcium":90,"iron":2.2},"tip":"韭菜叶一变深绿就关火，余温会让它刚好断生。"},
  {"id":"m89","name":"家常豆腐","type":"meat","spicy":true,"tags":["下饭","素荤搭配","经典川味"],"time":20,"difficulty":"简单","ingredients":[{"name":"老豆腐","amount":250,"unit":"g","category":"奶品豆制品"},{"name":"干香菇","amount":6,"unit":"g","category":"调味干货"},{"name":"青椒（菜椒不辣）","amount":40,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"白糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["老豆腐切三角厚片，干香菇提前用温水泡发切片，泡香菇水留用；青椒切块，蒜切片。","平底锅倒油 2 瓷勺，中火把豆腐两面各煎 2 分钟至金黄，盛出备用。","锅内余油小火炒香豆瓣酱 1 瓷勺和蒜片，下香菇片炒出香味。","加半碗泡香菇水、生抽 1 瓷勺和白糖 2 克烧开，放回豆腐中火烧 3 分钟入味。","下青椒块炒 30 秒，淋入水淀粉（玉米淀粉 1 小勺加 2 瓷勺清水调开）勾薄芡，翻匀出锅。"],"nutrition":{"kcal":280,"protein":20,"fat":17,"carbs":13,"calcium":320,"iron":4.5},"tip":"豆瓣酱本身够咸，一般不用再加盐；豆腐煎过再烧不易碎且更香。"},
  {"id":"m90","name":"滑蛋牛肉","type":"meat","spicy":false,"tags":["嫩滑","快手","孩子爱吃"],"time":15,"difficulty":"中等","ingredients":[{"name":"牛里脊","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"鸡蛋","amount":3,"unit":"个","category":"肉禽蛋"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["牛里脊逆纹切薄片，加生抽 1 瓷勺、料酒半瓷勺、玉米淀粉 1 小勺和少许油抓匀，腌 10 分钟。","鸡蛋加盐 1 克和 1 瓷勺清水打散，撒入葱花。","热锅倒油，大火把牛肉滑炒约 1 分钟至八成熟盛出，稍凉后放入蛋液中拌匀。","洗锅重新烧热，倒油 1 瓷勺，倒入牛肉蛋液，转小火用铲子缓慢推动。","蛋液半凝固、看起来还有一点稀时立即关火装盘，余温会让它刚好凝固。"],"nutrition":{"kcal":300,"protein":27,"fat":20,"carbs":4,"calcium":60,"iron":3.5},"tip":"关火时机是关键：蛋液看起来还有点稀就要出锅，余温会让它刚好凝固。"},
  {"id":"m91","name":"黄瓜炒鸡丁","type":"meat","spicy":false,"tags":["低脂","减脂餐","清爽"],"time":15,"difficulty":"简单","ingredients":[{"name":"鸡胸肉","amount":120,"unit":"g","category":"肉禽蛋"},{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鸡胸肉切 1.5 厘米小丁，加料酒半瓷勺、生抽 1 瓷勺、玉米淀粉 1 小勺和半勺清水抓到吸收，腌 10 分钟。","黄瓜、胡萝卜切丁；水开后胡萝卜丁先焯水 1 分钟捞出。","热锅倒油 1 瓷勺，下鸡丁中大火炒约 2 分钟至完全变白盛出。","底油爆香蒜末，下黄瓜丁和胡萝卜丁大火翻炒 1 分钟。","倒回鸡丁，加盐 1 克翻炒均匀即可出锅。"],"nutrition":{"kcal":220,"protein":28,"fat":8,"carbs":9,"calcium":25,"iron":1},"tip":"鸡胸腌时加半勺水抓到吸收，炒出来不柴。"},
  {"id":"m92","name":"香煎黄花鱼","type":"meat","spicy":false,"tags":["外酥里嫩","家常","高蛋白"],"time":20,"difficulty":"简单","ingredients":[{"name":"黄花鱼","amount":250,"unit":"g","category":"水产海鲜"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["黄花鱼处理干净，两面各划 2 刀，用盐 2 克、料酒 1 瓷勺和姜丝抹匀，腌 15 分钟。","用厨房纸把鱼身内外彻底吸干，两面薄拍一层玉米淀粉。","平底锅烧热倒油 2 瓷勺，油热放鱼，中小火煎 4 分钟，定型金黄后再翻面。","另一面再煎 3 分钟左右，至两面金黄酥脆出锅，撒葱花装盘。"],"nutrition":{"kcal":240,"protein":25,"fat":13,"carbs":5,"calcium":55,"iron":1.1},"tip":"鱼身擦得越干越不溅油也不粘锅；热锅凉油撒少许盐再放鱼，鱼皮更完整。","heavy":true},
  {"id":"br31","name":"牛肉末菠菜粥+水煮蛋","type":"breakfast","spicy":false,"tags":["补铁","暖胃","老少皆宜"],"time":30,"difficulty":"简单","ingredients":[{"name":"大米","amount":60,"unit":"g","category":"米面粮油"},{"name":"牛肉末","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"菠菜","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["大米淘洗后加约 6 倍清水，大火烧开转小火煮粥；另起小锅把鸡蛋煮 8 分钟，剥壳备用。","牛肉末加料酒半瓷勺和姜末拌匀去腥；菠菜焯水 30 秒捞出切碎。","粥煮约 20 分钟至软糯时下牛肉末，边倒边搅散，中火煮 3 分钟。","加入菠菜碎和盐 2 克，滴几滴香油关火，配水煮蛋食用。"],"nutrition":{"kcal":430,"protein":23,"fat":13,"carbs":55,"calcium":90,"iron":4.8},"tip":"牛肉末先用料酒姜末抓过再下锅，粥里不会有腥味；菠菜焯水去草酸。"},
  {"id":"br32","name":"鸡丝荞麦凉面+豆浆","type":"breakfast","spicy":false,"tags":["夏季","低GI","饱腹"],"time":20,"difficulty":"简单","ingredients":[{"name":"荞麦面","amount":80,"unit":"g","category":"米面粮油"},{"name":"鸡胸肉","amount":60,"unit":"g","category":"肉禽蛋"},{"name":"黄瓜","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"豆浆（或黄豆现打）","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香醋","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"白糖","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鸡胸肉冷水下锅，水开后转小火煮 12 分钟，关火焖 5 分钟，放温后撕成丝。","荞麦面煮 4 分钟左右至熟，过凉水沥干，拌少许香油防粘。","黄瓜切细丝；用生抽 1 瓷勺、香醋 1 瓷勺、蒜末、白糖 2 克和几滴香油调成料汁。","面条、鸡丝、黄瓜丝浇上料汁拌匀，配一杯温豆浆。"],"nutrition":{"kcal":460,"protein":30,"fat":10,"carbs":62,"calcium":60,"iron":3},"tip":"鸡胸煮好焖5分钟再捞更嫩；料汁可以前一晚调好冷藏。"},
  {"id":"br33","name":"全麦馒头夹煎蛋+纯牛奶","type":"breakfast","spicy":false,"tags":["10分钟","中式汉堡","补钙"],"time":10,"difficulty":"简单","ingredients":[{"name":"全麦馒头","amount":1,"unit":"个","category":"米面粮油"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"奶酪片","amount":1,"unit":"片","category":"奶品豆制品"},{"name":"生菜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"纯牛奶","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["全麦馒头对半剖开，上蒸锅蒸 3 分钟或微波炉加热 30 秒回软。","平底锅刷薄油，小火煎一个鸡蛋约 2 分钟，撒少许盐。","馒头依次夹入奶酪片、热煎蛋和生菜，奶酪被热气微微融化即可。","配一杯温牛奶食用。"],"nutrition":{"kcal":470,"protein":23,"fat":18,"carbs":55,"calcium":420,"iron":2.2},"tip":"奶酪片贴着热煎蛋放会自然融化，比冷夹好吃很多。"},
  {"id":"br34","name":"黑米红枣粥+奶酪蛋饼","type":"breakfast","spicy":false,"tags":["粗粮","补气色","香甜"],"time":35,"difficulty":"简单","ingredients":[{"name":"黑米","amount":30,"unit":"g","category":"米面粮油"},{"name":"大米","amount":30,"unit":"g","category":"米面粮油"},{"name":"红枣","amount":15,"unit":"g","category":"调味干货"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"面粉","amount":25,"unit":"g","category":"米面粮油"},{"name":"奶酪片","amount":1,"unit":"片","category":"奶品豆制品"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["黑米提前泡一晚，和大米、去核红枣一起加约 8 倍清水，大火烧开转小火煮 30 分钟成粥。","鸡蛋、面粉、盐 1 克和适量清水调成能缓缓流动的稀面糊，撒入葱花。","平底锅刷油，倒入面糊摊成薄饼，小火煎 1 分钟定型后放上奶酪片对折。","两面各再煎 1 分钟至微黄、奶酪融化，切块配粥食用。"],"nutrition":{"kcal":460,"protein":17,"fat":13,"carbs":68,"calcium":220,"iron":2.6},"tip":"黑米不泡很难煮烂，赶时间可用电饭煲预约功能夜里煮好。"},
  {"id":"br35","name":"金枪鱼鸡蛋三明治+酸奶","type":"breakfast","spicy":false,"tags":["高蛋白","免开火少油","带着走"],"time":15,"difficulty":"简单","ingredients":[{"name":"全麦吐司","amount":2,"unit":"片","category":"米面粮油"},{"name":"金枪鱼罐头","amount":60,"unit":"g","category":"水产海鲜"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"黄瓜","amount":40,"unit":"g","category":"蔬菜水果"},{"name":"酸奶","amount":100,"unit":"g","category":"奶品豆制品"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["鸡蛋冷水下锅煮 8 分钟，剥壳后用叉子压碎。","水浸金枪鱼沥干水分，与鸡蛋碎、1 瓷勺酸奶和少许黑胡椒拌成馅。","黄瓜切薄片铺在一片吐司上，抹上金枪鱼鸡蛋馅，盖上另一片吐司对切。","剩余酸奶直接食用。"],"nutrition":{"kcal":420,"protein":29,"fat":12,"carbs":46,"calcium":180,"iron":2.4},"tip":"用一勺酸奶代替沙拉酱拌馅，热量更低还带微微酸香。"},
  {"id":"br36","name":"番茄牛肉面","type":"breakfast","spicy":false,"tags":["一碗端","汤面","开胃"],"time":20,"difficulty":"简单","ingredients":[{"name":"挂面","amount":80,"unit":"g","category":"米面粮油"},{"name":"牛里脊","amount":60,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"上海青","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"食用油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["牛里脊逆纹切薄片，加生抽 1 瓷勺和玉米淀粉 1 小勺抓匀，腌 5 分钟。","热锅倒少许油，下番茄块中火炒 2 分钟出沙，加 2 碗热水烧开。","下挂面煮约 3 分钟至八成熟，放入牛肉片滑散再煮 1 分钟。","加上海青烫熟，加盐 2 克调味，撒葱花出锅。"],"nutrition":{"kcal":430,"protein":22,"fat":8,"carbs":66,"calcium":80,"iron":3.2},"tip":"牛肉片上浆后最后下锅，一变色就关火，嫩得像面馆的。"},
  {"id":"br37","name":"手抓饼肥牛卷+豆浆","type":"breakfast","spicy":false,"tags":["孩子爱吃","快手","解馋"],"time":15,"difficulty":"简单","ingredients":[{"name":"手抓饼","amount":1,"unit":"张","category":"米面粮油"},{"name":"肥牛卷","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"生菜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"豆浆（或黄豆现打）","amount":250,"unit":"ml","category":"奶品豆制品"},{"name":"生抽","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"黑胡椒","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["平底锅不放油，中火直接烙手抓饼，每面约 2 分钟至金黄起层，盛出。","用锅内余油把肥牛卷煎至变色，加生抽 1 瓷勺和少许黑胡椒调味。","手抓饼上铺生菜和肥牛，卷起后用厨房纸包住下半段方便拿取。","配一杯温豆浆食用。"],"nutrition":{"kcal":490,"protein":19,"fat":24,"carbs":50,"calcium":55,"iron":1.8},"tip":"手抓饼自带油脂，全程不用额外放油；肥牛煎出的油刚好用来提香。"},
  {"id":"br38","name":"香菇鸡丝粥+水煮鹌鹑蛋+上海青","type":"breakfast","spicy":false,"tags":["清淡养胃","广式风味","均衡"],"time":35,"difficulty":"简单","ingredients":[{"name":"大米","amount":70,"unit":"g","category":"米面粮油"},{"name":"鸡胸肉","amount":60,"unit":"g","category":"肉禽蛋"},{"name":"干香菇","amount":5,"unit":"g","category":"调味干货"},{"name":"鹌鹑蛋","amount":4,"unit":"个","category":"肉禽蛋"},{"name":"上海青","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"香油","amount":0,"unit":"适量","pantry":true,"category":"调味干货"},{"name":"玉米淀粉","amount":0,"unit":"适量","pantry":true,"category":"调味干货"}],"steps":["干香菇提前泡发切丝，大米加泡香菇水和清水共约 8 倍量，煮粥 25 分钟。","鸡胸切细丝，用盐 1 克和玉米淀粉半勺抓匀上薄浆；鹌鹑蛋煮 5 分钟剥壳。","粥浓稠后下香菇丝煮 5 分钟，再下鸡丝搅散煮 2 分钟至变白。","加盐 1 克和几滴香油调味；上海青开水烫 1 分钟，和鹌鹑蛋一起配粥。"],"nutrition":{"kcal":440,"protein":27,"fat":10,"carbs":62,"calcium":130,"iron":3.4},"tip":"鸡丝上薄浆再下粥里，口感嫩滑不柴；泡香菇水入粥更鲜。"},
  {"id":"v51","name":"芹菜炒香干","type":"veg","spicy":false,"tags":["高钙","快手","家常"],"time":10,"difficulty":"简单","ingredients":[{"name":"芹菜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"香干","amount":60,"unit":"g","category":"奶品豆制品"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["芹菜去叶洗净斜切成段，香干切薄片，蒜切片。","锅中水烧开，芹菜段焯水 30 秒捞出沥干，保持翠绿脆嫩。","热锅倒油 1 瓷勺，下蒜片爆香，放入香干片中火翻炒 1 分钟。","加入芹菜段大火快炒 1 分钟，加生抽半瓷勺和盐 1 克翻匀出锅。"],"nutrition":{"kcal":155,"protein":10,"fat":9,"carbs":8,"calcium":220,"iron":3},"tip":"芹菜先焯水能保持翠绿脆嫩，香干本身有咸味，盐要少放。"},
  {"id":"v53","name":"蒜蓉荷兰豆","type":"veg","spicy":false,"tags":["清爽","快手"],"time":8,"difficulty":"简单","ingredients":[{"name":"荷兰豆","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["荷兰豆撕去两侧老筋洗净，蒜剁成蒜蓉。","锅中水烧开，加少许盐和几滴油，荷兰豆焯水 1 分钟捞出沥干。","热锅倒油 1 瓷勺，小火把蒜蓉炒出香味。","倒入荷兰豆大火翻炒 1 分钟至熟透，加盐 1 克翻匀出锅。"],"nutrition":{"kcal":110,"protein":4,"fat":6,"carbs":10,"calcium":55,"iron":1.2},"tip":"荷兰豆一定要炒熟透再吃，焯水后快炒既安全又保持脆嫩。"},
  {"id":"v54","name":"清炒莴笋片","type":"veg","spicy":false,"tags":["清爽","低脂"],"time":8,"difficulty":"简单","ingredients":[{"name":"莴笋","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["莴笋削皮洗净，斜刀切成薄片，蒜切片。","热锅倒油 1 瓷勺，下蒜片爆香。","倒入莴笋片大火快炒 2 分钟至微微透亮。","加盐 1 克翻炒均匀即可出锅。"],"nutrition":{"kcal":75,"protein":2,"fat":5,"carbs":6,"calcium":45,"iron":1},"tip":"莴笋片切薄一点更容易熟，大火快炒口感脆嫩不出水。"},
  {"id":"v55","name":"凉拌千张丝","type":"veg","spicy":false,"tags":["凉菜","高蛋白","高钙"],"time":10,"difficulty":"简单","ingredients":[{"name":"千张","amount":50,"unit":"g","category":"奶品豆制品"},{"name":"黄瓜","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["千张切细丝，放入开水中焯 1 分钟去豆腥，捞出过凉水沥干。","黄瓜、胡萝卜洗净切细丝，蒜剁成蒜末。","三种丝放入大碗，加生抽 1 瓷勺、香醋 1 瓷勺、盐 1 克和蒜末。","淋上几滴香油拌匀，静置 5 分钟入味即可。"],"nutrition":{"kcal":175,"protein":13,"fat":10,"carbs":8,"calcium":180,"iron":2.5},"tip":"千张焯水能去豆腥味，口感也更软嫩，夏天吃特别清爽开胃。"},
  {"id":"v56","name":"蒜蓉粉丝蒸娃娃菜","type":"veg","spicy":false,"tags":["蒸菜","清淡"],"time":15,"difficulty":"简单","ingredients":[{"name":"娃娃菜","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"龙口粉丝","amount":20,"unit":"g","category":"米面粮油"},{"name":"蒜","amount":15,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蒸鱼豉油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["粉丝用温水泡 10 分钟至软；娃娃菜洗净竖切成条铺盘底，粉丝铺在上面。","蒜剁成蒜蓉，热锅倒油 1 瓷勺小火炒出香味，连油一起均匀铺在粉丝上。","蒸锅水开后放入，大火蒸 8 分钟取出。","淋上蒸鱼豉油 1 瓷勺，撒葱花，再烧 1 瓷勺热油浇上激香即可。"],"nutrition":{"kcal":150,"protein":3,"fat":6,"carbs":22,"calcium":60,"iron":1},"tip":"粉丝泡软即可不要泡太久，蒸的时候垫在娃娃菜上能吸饱汤汁。"},
  {"id":"v57","name":"蒜蓉炒茼蒿","type":"veg","spicy":false,"tags":["绿叶菜","快手","低脂"],"time":6,"difficulty":"简单","ingredients":[{"name":"茼蒿","amount":200,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":10,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["茼蒿去老根洗净沥干，切成长段，蒜拍碎切末。","热锅倒油 1 瓷勺，下蒜末爆香。","倒入茼蒿大火快炒 1 分钟至断生塌秧。","加盐 1 克翻匀立即出锅，久炒出水就不香了。"],"nutrition":{"kcal":80,"protein":3,"fat":5,"carbs":6,"calcium":90,"iron":2},"tip":"茼蒿易熟又易出水，全程大火快炒，断生就出锅香气最浓。"},
  {"id":"s33","name":"甜玉米鸡架汤","type":"soup","spicy":false,"tags":["清甜","鲜汤","实惠"],"time":60,"difficulty":"简单","ingredients":[{"name":"鸡架","amount":150,"unit":"g","category":"肉禽蛋"},{"name":"甜玉米","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":50,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡架斩块冷水下锅，加姜片和料酒 1 瓷勺，水开后焯 2 分钟，撇去浮沫捞出冲净。","甜玉米切段，胡萝卜切滚刀块。","鸡架、玉米、胡萝卜和姜片放入汤锅，加足量清水，大火烧开。","转小火盖盖炖 45 分钟，加盐 2 克调味，撒葱花即可。"],"nutrition":{"kcal":130,"protein":10,"fat":6,"carbs":12,"calcium":30,"iron":1},"tip":"鸡架便宜又出鲜，焯水去净血沫汤色才清亮，汤头一样鲜甜。"},
  {"id":"s34","name":"鲈鱼豆腐汤","type":"soup","spicy":false,"tags":["高蛋白","奶白鲜汤"],"time":30,"difficulty":"简单","ingredients":[{"name":"鲈鱼","amount":100,"unit":"g","category":"水产海鲜"},{"name":"嫩豆腐","amount":100,"unit":"g","category":"奶品豆制品"},{"name":"姜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鲈鱼切段，用料酒 1 瓷勺和姜片腌 10 分钟；嫩豆腐切块。","热锅倒油 1 瓷勺，下姜片，放入鱼段中火两面各煎 2 分钟至微黄。","冲入开水没过鱼身，保持大火滚煮 8 分钟至汤色奶白。","放入豆腐块再煮 5 分钟，加盐 2 克和少许黑胡椒调味，撒葱花即可。"],"nutrition":{"kcal":145,"protein":16,"fat":8,"carbs":3,"calcium":130,"iron":1.5},"tip":"鱼先煎再冲开水是汤色奶白的关键，全程保持大火滚煮。"},
  {"id":"s35","name":"番茄牛腩汤","type":"soup","spicy":false,"tags":["开胃","补铁"],"time":90,"difficulty":"简单","ingredients":[{"name":"牛腩","amount":50,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"番茄酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["牛腩切小块冷水下锅，加姜片和料酒 1 瓷勺焯水，捞出冲净浮沫。","番茄去皮切块；热锅倒少许油，先把一半番茄中火炒 2 分钟出沙，加番茄酱 1 小勺增色。","加入牛腩和足量热水，大火烧开转小火盖盖炖 1 小时至牛腩软烂。","放入剩余番茄块再煮 10 分钟，加盐 2 克调味，撒葱花即可。"],"nutrition":{"kcal":150,"protein":11,"fat":8,"carbs":9,"calcium":25,"iron":2.2},"tip":"番茄分两次放，第一次炖出浓汤底，第二次保留果肉口感。"},
  {"id":"s36","name":"海带豆腐汤","type":"soup","spicy":false,"tags":["素汤","高钙","低脂"],"time":25,"difficulty":"简单","ingredients":[{"name":"海带","amount":50,"unit":"g","category":"水产海鲜"},{"name":"老豆腐","amount":80,"unit":"g","category":"奶品豆制品"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["海带提前泡发，洗净表面黏液切菱形片；老豆腐切小块。","锅中加约 3 碗清水和姜片烧开，放入海带中火煮 10 分钟。","加入豆腐块再煮 8 分钟。","加盐 2 克调味，滴几滴香油，撒葱花即可。"],"nutrition":{"kcal":85,"protein":8,"fat":4,"carbs":6,"calcium":200,"iron":1.8},"tip":"海带提前泡发洗净表面黏液，汤更清爽，钙含量高很适合孩子。"},
  {"id":"s37","name":"白萝卜鸡腿汤","type":"soup","spicy":false,"tags":["清润","鲜汤"],"time":45,"difficulty":"简单","ingredients":[{"name":"鸡腿肉","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"白萝卜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"枸杞","amount":3,"unit":"g","category":"调味干货"},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["鸡腿肉切块冷水下锅，加姜片和料酒 1 瓷勺焯水，捞出冲净。","白萝卜削皮切滚刀块。","鸡腿肉、白萝卜和姜片入锅，加足量清水，大火烧开转小火炖 35 分钟至萝卜半透明。","加盐 2 克调味，撒入枸杞焖 2 分钟即可。"],"nutrition":{"kcal":140,"protein":13,"fat":8,"carbs":6,"calcium":30,"iron":1.2},"tip":"萝卜炖到半透明最好喝，不喜欢油可以先把鸡腿去皮。"},
  {"id":"s38","name":"苋菜蛋花汤","type":"soup","spicy":false,"tags":["补铁","快手","素汤"],"time":10,"difficulty":"简单","ingredients":[{"name":"苋菜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["苋菜择洗干净切段，鸡蛋打散。","热锅倒少许油，爆香蒜片，下苋菜略炒 30 秒。","加约 2 碗清水烧开，煮 2 分钟至汤色微微泛红。","沿锅边转圈缓缓淋入蛋液，凝成蛋花后加盐 2 克，滴几滴香油即可。"],"nutrition":{"kcal":100,"protein":8,"fat":6,"carbs":4,"calcium":130,"iron":3},"tip":"苋菜煮出的红汤是天然色素，铁和钙都丰富，蛋液沿锅边慢慢淋才有漂亮蛋花。"},
  {"id":"s39","name":"奶香南瓜浓汤","type":"soup","spicy":false,"tags":["香甜","老少皆宜"],"time":20,"difficulty":"简单","ingredients":[{"name":"南瓜","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"纯牛奶","amount":100,"unit":"ml","category":"奶品豆制品"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["南瓜去皮去瓤切薄片，水开后上锅蒸 12 分钟，至筷子能轻松扎透。","蒸好的南瓜加少量温水，用料理机打成细腻的糊。","南瓜糊倒回锅中小火加热，倒入纯牛奶搅匀。","边搅边煮至微微冒泡就关火，按口味加一点点盐或白糖调味。"],"nutrition":{"kcal":110,"protein":4,"fat":3.5,"carbs":16,"calcium":120,"iron":0.6},"tip":"牛奶最后放且不要大火久煮，避免结皮，汤更顺滑奶香。"},
  {"id":"s40","name":"莲藕甜玉米素汤","type":"soup","spicy":false,"tags":["素汤","清甜"],"time":40,"difficulty":"简单","ingredients":[{"name":"莲藕","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"甜玉米","amount":60,"unit":"g","category":"蔬菜水果"},{"name":"胡萝卜","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"干香菇","amount":3,"unit":"g","category":"调味干货"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["干香菇提前泡发，泡香菇水过滤留用；莲藕削皮切块，甜玉米切段，胡萝卜切滚刀块。","所有食材和姜片放入汤锅，加清水和香菇水共约 4 碗。","大火烧开后转小火，盖盖炖 30 分钟至莲藕粉糯。","加盐 2 克调味即可，汤清味甜。"],"nutrition":{"kcal":105,"protein":3,"fat":1,"carbs":22,"calcium":30,"iron":1},"tip":"香菇水是素汤的鲜味来源，别倒掉；藕选粉藕炖出来更绵甜。"},
  {"id":"st16","name":"紫薯米饭","type":"staple","spicy":false,"tags":["粗粮","膳食纤维"],"time":40,"difficulty":"简单","ingredients":[{"name":"大米","amount":50,"unit":"g","category":"米面粮油"},{"name":"紫薯","amount":80,"unit":"g","category":"蔬菜水果"}],"steps":["大米淘洗两遍放入电饭煲，加平时煮饭等量的水。","紫薯削皮切成 1.5 厘米小丁，均匀铺在大米上，不用搅拌。","按下煮饭键，跳闸后再焖 10 分钟。","开盖用饭勺把紫薯和米饭轻轻拌匀即可。"],"nutrition":{"kcal":255,"protein":4.5,"fat":0.6,"carbs":58,"calcium":20,"iron":0.8},"tip":"紫薯丁不用额外加水，蒸出的花青素会把米饭染成漂亮的淡紫色。"},
  {"id":"st17","name":"南瓜小米粥","type":"staple","spicy":false,"tags":["粗粮","养胃"],"time":35,"difficulty":"简单","ingredients":[{"name":"小米","amount":65,"unit":"g","category":"米面粮油"},{"name":"南瓜","amount":100,"unit":"g","category":"蔬菜水果"}],"steps":["小米淘洗干净，南瓜去皮去瓤切小丁。","锅中加约 800 毫升清水烧开，倒入小米和南瓜丁。","再次煮开后转小火，盖上盖子留一条缝熬 25 分钟。","中途搅拌两三次防粘底，熬至南瓜融化、粥面浮起一层米油即可。"],"nutrition":{"kcal":260,"protein":6.5,"fat":2.2,"carbs":55,"calcium":25,"iron":2},"tip":"水开后再下小米不易粘锅，南瓜熬化后粥自带清甜，不用加糖。"},
  {"id":"v59","name":"清炒茼蒿","type":"veg","spicy":false,"tags":["绿叶菜","快手","时令"],"time":8,"difficulty":"简单","ingredients":[{"name":"茼蒿","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["茼蒿洗净沥干，切两段。","热锅热油爆香蒜片。","下茼蒿最大火快炒 40 秒至刚塌秧。","加盐翻匀立刻出锅，久炒出水就不香了。"],"nutrition":{"kcal":60,"protein":3,"fat":4,"carbs":5,"calcium":70,"iron":1.8},"tip":"茼蒿自带清香，钙和胡萝卜素都不低，是火锅之外被低估的绿叶菜。"},
  {"id":"v60","name":"凉拌海带丝","type":"veg","spicy":false,"tags":["凉拌","补碘","成本超低"],"time":15,"difficulty":"简单","ingredients":[{"name":"海带","amount":100,"unit":"g","category":"蔬菜水果","note":"选海带丝更省事"},{"name":"蒜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["海带丝洗净，沸水煮 5 分钟捞出过凉水，口感更脆。","蒜剁成末，加香醋 2 瓷勺、生抽 1 瓷勺和几滴香油调成料汁。","海带丝挤干水分，浇上料汁拌匀。","撒葱花，冷藏 10 分钟更入味。"],"nutrition":{"kcal":50,"protein":2,"fat":3,"carbs":6,"calcium":90,"iron":1},"tip":"海带是碘和可溶性膳食纤维的优质来源，凉拌爽脆开胃，两三块钱一大盘。"},
  {"id":"m93","name":"口蘑牛肉","type":"meat","spicy":false,"tags":["补铁","高蛋白","快手"],"time":20,"difficulty":"中等","ingredients":[{"name":"牛里脊","amount":100,"unit":"g","category":"肉禽蛋"},{"name":"口蘑","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"蚝油","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["牛里脊逆纹切薄片，加生抽、料酒、淀粉抓匀腌 10 分钟。","口蘑切厚片，干锅煸 2 分钟逼出水分盛出。","热锅热油下牛肉大火快炒至变色盛出。","底油爆香蒜片，倒回口蘑和牛肉，加蚝油、黑胡椒大火翻匀出锅。"],"nutrition":{"kcal":240,"protein":23,"fat":13,"carbs":8,"calcium":25,"iron":3.2},"tip":"口蘑的鲜味物质与牛肉是天然增鲜组合；牛肉逆纹切、大火快炒是嫩的关键。"},
  {"id":"st18","name":"番茄肉酱意面","type":"staple","spicy":false,"tags":["儿童最爱","西式","一锅出"],"time":25,"difficulty":"简单","ingredients":[{"name":"意大利面","amount":70,"unit":"g","category":"米面粮油"},{"name":"牛肉末","amount":40,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":120,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"番茄酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"黑胡椒","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["意面下加了盐的沸水煮 8-10 分钟，捞出拌少许油防粘，留一碗煮面水。","蒜末炒香，下牛肉末炒散至变色。","下番茄丁炒出沙，加番茄酱 2 勺和半碗煮面水，中火熬浓。","倒入意面翻拌裹匀酱汁，撒黑胡椒出锅。"],"nutrition":{"kcal":420,"protein":18,"fat":10,"carbs":65,"calcium":40,"iron":2.8},"tip":"作为主食出现时热量比米饭高，当天搭配的荤素菜会自动平衡；孩子接受度极高的一餐。","solo":true},
  {"id":"m94","name":"豆豉鲮鱼茄子","type":"meat","spicy":false,"tags":["广东家常","下饭神器","开罐即烹"],"time":15,"difficulty":"简单","ingredients":[{"name":"豆豉鲮鱼罐头","amount":60,"unit":"g","category":"水产海鲜","note":"约半罐"},{"name":"茄子","amount":150,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["茄子切长条，少油煎至变软微焦（或上锅蒸 8 分钟更省油）。","豆豉鲮鱼掰成小块，连罐里的豆豉和油一起备用。","爆香蒜末，下茄子和鲮鱼豆豉翻炒。","加生抽和两勺水焖 2 分钟收汁，撒葱花出锅，拌饭一绝。"],"nutrition":{"kcal":250,"protein":15,"fat":16,"carbs":10,"calcium":180,"iron":2},"tip":"鲮鱼罐头连骨可食、钙含量可观；罐头钠偏高，这道菜基本不用再加盐。"},
  {"id":"m95","name":"黄瓜鸡蛋炒火腿肠","type":"meat","spicy":false,"tags":["快手","儿童最爱","成本超低"],"time":10,"difficulty":"简单","ingredients":[{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"鸡蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"火腿肠","amount":40,"unit":"g","category":"肉禽蛋","note":"约 1 根"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"食盐","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["黄瓜切菱形片，火腿肠切片，鸡蛋加盐 1 克打散。","热锅倒油 1 瓷勺，倒入蛋液，凝固后划散盛出。","底油爆香蒜片，下火腿肠中火煎出微焦边。","下黄瓜大火炒 30 秒，倒回鸡蛋翻匀；火腿肠和蛋已带咸味，尝一下不够再补盐。"],"nutrition":{"kcal":220,"protein":12,"fat":15,"carbs":9,"calcium":45,"iron":1.6},"tip":"十分钟快手菜，色彩讨喜孩子爱吃；火腿肠钠和脂肪偏高，靠鸡蛋和黄瓜平衡，别再多放盐。"},
  {"id":"v61","name":"日式清拌黄瓜","type":"veg","spicy":false,"tags":["凉拌","爽口","低卡"],"time":10,"difficulty":"简单","ingredients":[{"name":"黄瓜","amount":130,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"白糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["黄瓜切薄圆片，加盐 2 克抓匀腌 5 分钟，挤去水分，这是脆的关键。","姜切细末，加生抽 1 瓷勺、香醋 1.5 瓷勺、白糖 2 克和几滴香油调成料汁。","料汁浇入黄瓜拌匀。","冷藏 10 分钟风味更清爽，用小碗装盘更有日式味道。"],"nutrition":{"kcal":45,"protein":1,"fat":2,"carbs":6,"calcium":25,"iron":0.4},"tip":"盐腌挤水让黄瓜久放不出水、口感清脆；低卡爽口，适合给油腻的一餐解腻。"},
  {"id":"v62","name":"黄瓜拌蟹柳","type":"veg","spicy":false,"tags":["凉拌","快手","儿童友好"],"time":10,"difficulty":"简单","ingredients":[{"name":"黄瓜","amount":100,"unit":"g","category":"蔬菜水果"},{"name":"蟹柳","amount":50,"unit":"g","category":"水产海鲜"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香醋","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"香油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["蟹柳沸水烫 1 分钟捞出放凉，撕成细丝。","黄瓜切细丝，或拍碎后切段。","蒜末加生抽 1 瓷勺、香醋 1 瓷勺和几滴香油调成料汁。","黄瓜与蟹柳丝浇上料汁拌匀即可，冰镇后更好吃。"],"nutrition":{"kcal":90,"protein":7,"fat":3,"carbs":9,"calcium":40,"iron":0.6},"tip":"蟹柳是鱼糜制品，蛋白质不错但含钠较高，料汁里生抽少放一点即可。"},
  {"id":"st19","name":"台式牛肉面","type":"staple","spicy":false,"tags":["硬菜级主食","周末慢炖","一碗管饱"],"time":100,"difficulty":"中等","ingredients":[{"name":"挂面","amount":80,"unit":"g","category":"米面粮油","note":"选宽面更地道"},{"name":"牛腩","amount":80,"unit":"g","category":"肉禽蛋"},{"name":"番茄","amount":80,"unit":"g","category":"蔬菜水果"},{"name":"上海青","amount":40,"unit":"g","category":"蔬菜水果"},{"name":"姜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":8,"unit":"g","category":"蔬菜水果"},{"name":"豆瓣酱","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"老抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"冰糖","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"八角","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"料酒","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["牛腩切块冷水下锅，加姜片和料酒 1 瓷勺焯水，捞出冲净。","热锅倒少许油，下姜蒜和豆瓣酱半瓷勺，小火炒出红油。","下牛腩和番茄块翻炒 2 分钟，加老抽半瓷勺、冰糖 3 克、1 个八角和热水没过食材。","小火盖盖炖 80 分钟（高压锅上汽后 30 分钟），至牛腩用筷子能轻松扎透。","另锅煮面并烫熟上海青，捞入碗中，浇上牛肉和汤即成。"],"nutrition":{"kcal":480,"protein":25,"fat":14,"carbs":65,"calcium":50,"iron":3.5},"tip":"豆瓣酱用量减半就是孩子也能吃的家庭版；汤头咸度足，面里不用再加盐。","solo":true},
  {"id":"m96","name":"皮蛋炒鸡蛋","type":"meat","spicy":false,"tags":["下饭","快手","成本超低"],"time":10,"difficulty":"简单","ingredients":[{"name":"皮蛋","amount":1,"unit":"个","category":"肉禽蛋"},{"name":"鸡蛋","amount":1.5,"unit":"个","category":"肉禽蛋"},{"name":"青椒（菜椒不辣）","amount":30,"unit":"g","category":"蔬菜水果"},{"name":"蒜","amount":5,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["皮蛋蒸 2 分钟定型（溏心不散的窍门），切小瓣。","鸡蛋打散，热锅热油炒至半凝固盛出。","底油爆香蒜末和青椒片，下皮蛋煎出焦边。","倒回鸡蛋，淋生抽大火翻匀出锅。"],"nutrition":{"kcal":230,"protein":14,"fat":17,"carbs":4,"calcium":65,"iron":3},"tip":"双蛋组合的下饭菜；皮蛋先蒸再切不粘刀不散心。钠偏高，幼儿少量尝味即可。"},
  {"id":"st20","name":"雪菜肉丝面","type":"staple","spicy":false,"tags":["江南风味","开胃","一碗管饱"],"time":20,"difficulty":"简单","ingredients":[{"name":"挂面","amount":80,"unit":"g","category":"米面粮油"},{"name":"雪菜","amount":50,"unit":"g","category":"蔬菜水果","note":"袋装雪菜碎"},{"name":"猪里脊肉","amount":40,"unit":"g","category":"肉禽蛋"},{"name":"姜","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"小葱","amount":3,"unit":"g","category":"蔬菜水果"},{"name":"生抽","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"玉米淀粉","amount":0,"unit":"适量","category":"调味干货","pantry":true},{"name":"食用油","amount":0,"unit":"适量","category":"调味干货","pantry":true}],"steps":["肉丝加生抽、淀粉腌 5 分钟；雪菜冲洗一遍挤干（去多余咸味）。","热锅热油滑散肉丝至变色，下姜丝和雪菜翻炒 1 分钟。","加两碗热水烧开成汤底。","另锅煮面捞入碗中，浇上雪菜肉丝和汤，撒葱花。"],"nutrition":{"kcal":440,"protein":19,"fat":9,"carbs":70,"calcium":80,"iron":2.6},"tip":"江南人的开胃面；雪菜自带咸鲜，冲洗后基本不用加盐，汤也别喝太多。","solo":true}
